window.EN_RECIPES = Object.assign(window.EN_RECIPES || {}, {
  "x_sg_curry_puff": {n:"Curry puffs with potato and egg", how:["Take 60 g butter out of the fridge 20 minutes before you start so it softens.", "Mix 250 g flour with a pinch of salt, add the soft butter and rub it in with your fingers to fine crumbs.", "Pour in 90 ml cold water, knead into a smooth dough, cover with cling film and rest for 20 minutes.", "While the dough rests, peel 300 g potatoes, cut into 1 cm cubes and boil in salted water for 8 minutes until tender but not falling apart, then drain in a colander.", "Meanwhile, put the egg in cold water, bring to a boil and cook for 10 minutes, cool in cold water, peel and cut into 8 wedges.", "Finely dice 100 g onion and fry in 1 tbsp oil over medium heat for 5 minutes until translucent.", "Add 2 tsp curry powder and toast for 1 minute until fragrant, then add the potatoes, 2 tsp sugar and salt.", "Stir, mash half the cubes with a fork and let the filling cool completely, about 15 minutes.", "Roll the dough out 3 mm thick and cut 10 cm rounds, gathering and re-rolling the scraps.", "Put a spoonful of filling and an egg wedge on each round, fold into a half-moon and crimp the edge into a rope pattern, pressing firmly.", "Heat the remaining oil in a deep frying pan over medium heat to 170 °C: a scrap of dough should sizzle at once.", "Fry the puffs 3-4 at a time for 3-4 minutes, turning, until evenly golden.", "Drain on paper towels and let stand for 5 minutes so the pastry crisps up and the filling is no longer scalding."], tip:"Only add the filling once it is completely cold, otherwise the butter in the dough melts and the edge splits open during frying.", side:"Sweet milk tea", next:{n:"Reheated curry puffs for a snack", how:["Take the puffs out of the fridge 15 minutes before reheating.", "Warm them in a dry frying pan, covered, over low heat for 4-5 minutes, turning once.", "Uncover and cook 1 minute more so the crust turns crisp again."]}, alt:{airfryer:"Instead of deep-frying: brush the puffs with 1 tbsp oil, 180 °C, 12-14 minutes, turning at minute 7.", oven:"Instead of deep-frying: brush the puffs with oil, place on baking paper, 200 °C, 20-25 minutes until golden."}},
  "x_sg_hotplate_tofu": {n:"Hotplate tofu with egg and vegetables", how:["Take the broccoli out of the freezer and leave it in a bowl for 10 minutes so the florets separate easily.", "Rinse 180 g rice until the water runs clear, add 360 ml water, bring to a boil and cook covered over low heat for 15 minutes.", "While the rice cooks, pat 400 g tofu dry with a towel, cut into 3 cm cubes and coat in half the flour, about 15 g.", "Slice 150 g mushrooms 5 mm thick, break the broccoli into 3 cm florets, thinly slice 80 g carrot into rounds, and finely chop 20 g garlic and 10 g ginger.", "Whisk 40 ml soy sauce, 2 tsp sugar, the remaining flour and 150 ml water until smooth.", "Heat 3 tbsp oil in a frying pan over medium heat and fry the tofu for 6-7 minutes, turning, until golden on all sides, then transfer to a plate.", "In the oil left in the pan, fry the garlic and ginger for 30 seconds until fragrant.", "Add the carrot and broccoli and fry for 3 minutes, then the mushrooms for 3 minutes more until soft.", "Pour in the sauce and heat for 1-2 minutes, stirring, until it thickens and turns glossy.", "Return the tofu and fold gently so the cubes don't break, then take off the heat.", "Beat 2 eggs with a fork until smooth.", "Get a second pan, ideally cast iron, very hot with 1 tsp oil, pour in the eggs about 1 cm deep and immediately top with the tofu, vegetables and sauce.", "As soon as the egg edges set and start to crackle, after about 1 minute, serve straight from the pan with hot rice."], tip:"Pour the egg only into a very hot pan: it should sizzle and set underneath while staying soft on top under the sauce.", side:"", next:{n:"Fried rice with tofu and vegetables", how:["Heat a frying pan over high heat with 1 tsp oil.", "Add the leftover rice and fry for 3 minutes, breaking up any clumps.", "Add the leftover tofu with vegetables, sauce and bits of egg and fry 3 minutes more, stirring.", "Season with soy sauce to taste and serve hot."]}, alt:{wok:"Cook the vegetables and sauce in a wok over high heat, same frying times.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot on the stove."}},
  "x_sg_roti_john": {n:"Roti John: omelette and mince baguette", how:["Finely dice 100 g onion, cut 50 g sweet pepper into 5 mm dice, crush and chop 10 g garlic.", "Slice 100 g cucumber thinly on the diagonal and refrigerate until serving.", "Heat a dry frying pan over high heat and fry 200 g mince for 5 minutes, breaking it into fine crumbs with a spatula, until no pink remains.", "Add half the onion, the pepper, garlic, 1 tsp curry powder and salt and fry 2 minutes more.", "Transfer the mince to a bowl and cool for 3 minutes so the heat doesn't cook the eggs.", "Beat 3 eggs with a fork with the remaining onion and a pinch of salt, then combine with the mince.", "Cut the baguette crosswise into 2 pieces of 20 cm, slit each lengthwise without cutting all the way through and open like a book.", "Melt 10 g butter in a frying pan over medium heat and pour in half the egg mixture in a patch the size of the bread.", "Immediately press the bread, cut side down, onto the runny omelette and fry for 2-3 minutes until the egg sets and sticks.", "Flip and toast the crust for 1 minute, then move to a board.", "Repeat with the remaining 10 g butter, egg mixture and second piece of baguette.", "Cut into 4 cm slices, top with cucumber and drizzle mayonnaise and ketchup over in a criss-cross pattern."], tip:"Press the bread onto the omelette while the top is still runny, otherwise the filling won't stick to the crumb and will fall off when you slice it.", side:"Fresh cucumbers", next:{n:"Hot Roti John sandwiches for lunch", how:["Store the leftovers without cucumber and sauces in a container.", "Reheat the slices omelette side down in a dry frying pan over low heat for 2-3 minutes.", "Flip and warm the crust for 1 minute.", "Top with fresh cucumber and drizzle with mayonnaise and ketchup."]}, alt:{}},
  "x_sg_fish_bee_hoon": {n:"Fish bee hoon: fish soup with rice vermicelli", how:["Cut 350 g cod fillet into 3 cm pieces, salt and leave for 10 minutes.", "Slice 30 g ginger into thin coins and 20 g garlic into slices.", "Cut 200 g tomatoes into wedges, rinse the spinach, remove thick stems and tear roughly by hand.", "Soak 150 g rice noodles in hot water for 10 minutes until soft.", "While the noodles soak, heat 1 tbsp oil in a saucepan over medium heat and fry the ginger and garlic for 1 minute until the edges are golden.", "Pour in 800 ml water, add the tomatoes, bring to a boil and simmer over medium heat for 10 minutes until the broth turns pinkish and slightly sour.", "Drain the noodles in a colander and divide among deep bowls.", "Reduce to low heat, add the fish and poach for 4-5 minutes until the flesh turns white and starts to flake.", "Add 2 tbsp fish sauce and 200 ml milk and heat for 1 minute without letting it boil hard, so the milk doesn't curdle.", "Add the spinach for 30 seconds, season with mixed pepper and taste for salt.", "Ladle the soup with fish and vegetables over the noodles and serve at once."], tip:"Add the milk at the very end over low heat: it gives Singaporean fish soup its gentle, creamy flavour without heaviness.", side:"", next:null, alt:{multi:"Ginger and garlic on \"Fry\" for 2 minutes, then water and tomatoes on \"Soup\" for 15 minutes, fish on \"Boil\" for 5 minutes, milk and spinach at the very end."}},
  "x_se_toast_skagen": {n:"Toast Skagen: Swedish shrimp toast", how:["If the shrimp are frozen, thaw them in the fridge ahead of time or in a bowl under cold running water for 10 minutes.", "If the shrimp are raw, drop them into boiling salted water for 2-3 minutes until pink, cool in cold water and peel.", "Pat 250 g shrimp dry with a towel and cut into 2-3 pieces, keeping 6 whole for garnish.", "Dice 30 g onion very finely, 2-3 mm, and finely chop the dill, reserving a few sprigs.", "Finely grate the zest from half a lemon and squeeze 1 tbsp juice; cut the other half into wedges.", "Mix 3 tbsp mayonnaise with 80 g sour cream, then add the onion, chopped dill, zest and juice.", "Gently fold in the shrimp and refrigerate the mixture for 10 minutes.", "While it chills, cut the bread into 4 slices 1.5 cm thick and trim off the crusts.", "Melt 30 g butter in a frying pan over medium heat.", "Fry the slices for 2 minutes per side until crisp and golden, then let cool for 1 minute.", "Salt the shrimp mixture at the last moment and pile it onto the toasts.", "Garnish with the whole shrimp, dill sprigs and lemon wedges and serve at once."], tip:"Salt the shrimp mixture just before serving and don't stir it for long, otherwise the shrimp release their juices and the sauce turns watery.", side:"Light cucumber salad", next:{n:"Skagen sandwich for lunch", how:["Store the shrimp mixture separately from the bread in a covered bowl for no more than a day.", "Toast 2 slices of bread in a dry frying pan for 1 minute per side.", "Spread the mixture on one slice, add a sprig of dill and cover with the second slice.", "Sprinkle with lemon juice and cut in half."]}, alt:{airfryer:"Toasts: brush both sides with melted butter, 190 °C, 4-5 minutes without turning."}},
  "x_se_pytt_i_panna": {n:"Pytt i panna: Swedish hash with egg and pickled beetroot", how:["Peel 150 g beetroot and cut into 3 mm matchsticks.", "Cover the beetroot with 150 ml water, add 20 ml vinegar, 2 tsp sugar and a pinch of salt, simmer over medium heat for 15 minutes until tender, then let cool in the pickling liquid.", "While the beetroot cooks, peel 500 g potatoes, cut into even 1 cm cubes, rinse in cold water and dry thoroughly with a towel.", "Heat 30 ml vegetable oil in a large frying pan over medium heat and spread the potatoes in a single layer.", "Fry for 15-18 minutes, turning every 3-4 minutes, until golden outside and tender inside.", "Meanwhile, cut 200 g sausages into 1 cm cubes and finely dice 150 g onion.", "Add 15 g butter, the onion and sausages to the potatoes and fry for 6-7 minutes until the onion is golden and the sausages are browned.", "Finely chop the parsley, season the potatoes with salt and pepper and stir in half the herbs.", "Turn the heat down to the lowest setting so the hash stays warm while the eggs fry.", "In another pan, melt the remaining 15 g butter and fry 2 eggs sunny side up over medium heat for 3 minutes, keeping the yolks runny.", "Divide the hash among plates, top each with an egg, add the drained pickled beetroot alongside and sprinkle with the remaining parsley."], tip:"Fry the potatoes until crisp on their own and only then add the sausage and onion: if everything goes in at once, the cubes steam and stick together.", side:"", next:{n:"Potato omelette from leftover pytt i panna", how:["Reheat the leftovers in a frying pan with 1 tsp butter over medium heat for 4 minutes.", "Beat 2 eggs with a pinch of salt and pour over the potatoes.", "Cover and cook over low heat for 4-5 minutes until the egg sets.", "Cut into quarters and serve with the pickled beetroot."]}, alt:{airfryer:"Potato cubes: drizzle with oil, 200 °C, 20 minutes, shaking every 5 minutes, then combine with the sausages and onion fried in a pan."}},
  "x_se_nasselsoppa": {n:"Nässelsoppa: Swedish green soup with spinach and egg", how:["Put 2 eggs into boiling water and cook for 7 minutes, then transfer to ice water for 5 minutes.", "While the eggs cook, finely dice 100 g onion and cut 250 g potatoes into 1 cm cubes.", "Wash 2 bunches of spinach in several changes of water and remove the thick stems.", "Melt 30 g butter in a pot over medium heat and sweat the onion for 4 minutes until soft without letting it colour.", "Add 20 g flour, a heaped tablespoon, and stir for 1 minute.", "Gradually pour in 600 ml hot water, whisking so no lumps form.", "Add the potatoes, salt, bring to a boil and simmer over low heat for 12 minutes until tender.", "Peel the eggs and cut them in half.", "Add the spinach and cook for exactly 2 minutes so the leaves wilt but stay bright green.", "Take the pot off the heat and blend the soup with a stick blender until smooth.", "Pour in 200 ml milk and warm over low heat for 2 minutes without boiling, then taste for salt.", "Ladle into bowls, place 2 egg halves in each and serve with a slice of bread."], tip:"Don't cook the spinach for more than 2 minutes and blend straight away, otherwise the soup turns a murky grey, and the Swedish version should be bright green.", side:"", next:null, alt:{multi:"Onion on \"Fry\" for 5 minutes, then flour, water and potatoes on \"Soup\" for 15 minutes, spinach for 2 minutes, then blend."}},
  "x_se_vasterbottenpaj": {n:"Västerbotten cheese pie", how:["Cut 60 g cold butter into 1 cm cubes and chill for 10 minutes.", "Mix 120 g flour with a pinch of salt, add the butter and quickly rub it in with your fingertips to crumbs.", "Add 2 tbsp ice water and gather the dough into a ball without kneading for long.", "Roll the dough out 3 mm thick, line an 18-20 cm tin with 3 cm sides and prick the base with a fork.", "Chill the tin for 15 minutes and meanwhile preheat the oven to 200 °C.", "Cover the pastry with baking paper, set a smaller tin on top as a weight and bake for 12 minutes.", "Remove the weight and paper and bake 5 minutes more until the base is dry and pale, then lower the temperature to 175 °C.", "While the case bakes, finely grate 120 g cheese.", "Whisk 2 eggs with 150 ml cream, add the cheese, season with mixed pepper and stir.", "Pour the filling into the hot case and bake at 175 °C for 25-30 minutes until the centre no longer wobbles and the top is golden.", "Let the pie cool in the tin for 10 minutes so the filling sets.", "Cut into 6 pieces and serve warm or at room temperature."], tip:"Always blind-bake the case first, otherwise the creamy filling soaks into the pastry and the base stays raw.", side:"Fresh green salad", next:{n:"Warm cheese pie for breakfast", how:["Cut the cold pie into pieces.", "Warm the pieces in a dry frying pan, covered, over low heat for 5 minutes so the base turns crisp again.", "Serve warm with tea or coffee."]}, alt:{airfryer:"For a tin up to 18 cm: case at 180 °C for 10 minutes, with filling at 160 °C for 20-25 minutes; if the top browns too fast, cover it with foil."}},
  "x_tj_nahud_shurak": {n:"Nakhud shurak: chickpeas with pickled onion and herbs", how:["Sort 200 g chickpeas, rinse and soak in three times their volume of cold water for 8-10 hours, ideally overnight.", "Drain, transfer the chickpeas to a pot, add 1.5 l fresh water and bring to a boil over high heat.", "Skim off the foam, reduce to low heat and simmer with the lid ajar for 60-70 minutes.", "While the chickpeas cook, slice 200 g onion into thin half-rings.", "Pour 30 ml vinegar mixed with 50 ml water and a pinch of salt over the onion, stir and leave for 20 minutes.", "10 minutes before the end, salt the chickpea water: by now the chickpeas should squash fairly easily between your fingers.", "Toast 1 tsp cumin seeds in a dry frying pan over medium heat for 30 seconds until fragrant and crush lightly.", "Finely chop the coriander and dill.", "Squeeze the vinegar out of the pickled onion.", "Drain the hot chickpeas, reserving half a glass of the cooking liquid, and transfer to a wide bowl.", "Drizzle the chickpeas with 20 ml oil and the cooking liquid, sprinkle with cumin and mixed pepper, and toss.", "Top with the onion and herbs and serve warm with torn flatbread."], tip:"Always squeeze the onion after pickling: excess vinegar will overpower the chickpeas, and shurak should be only gently tangy.", side:"", next:{n:"Flatbread with warm chickpeas and onion", how:["Reheat the leftover chickpeas in a frying pan with 1 tsp oil for 3 minutes.", "Split the flatbread and warm it in a dry frying pan for 1 minute.", "Fill the flatbread with the chickpeas, pickled onion and herbs.", "Sprinkle with mixed pepper and roll up."]}, alt:{pressure:"Cover the soaked chickpeas with 1 l water: 25 minutes under pressure with natural release instead of an hour of simmering.", multi:"\"Beans\" or \"Stew\" mode for 1.5 hours instead of simmering on the stove."}},
  "x_tj_umoch": {n:"Umoch: Tajik soup with flour pellets", how:["Put 100 g flour in a wide bowl and sprinkle with cold water 1 tbsp at a time, rubbing with your fingers until the flour clumps into pellets the size of rice grains.", "Shake the pellets through a coarse sieve to remove loose flour and leave them to dry for 10 minutes.", "While they dry, slice 150 g onion into half-rings, 100 g carrot into matchsticks and 100 g sweet pepper into strips.", "Cut 250 g tomatoes into 1 cm dice and 200 g potatoes into 1.5 cm cubes, and bring 1 l water to a boil.", "Heat 40 ml oil in a pot over medium heat and fry the onion for 4 minutes until golden.", "Add the carrot and pepper and fry 3 minutes more, stirring.", "Add the tomatoes and cook for 5 minutes until they release their juice and turn into a sauce.", "Pour in 1 l boiling water, add the potatoes, 1 tsp cumin and salt and cook over medium heat for 10 minutes.", "Add the pellets in a thin stream, stirring constantly so they don't stick together.", "Cook for 5-7 minutes until the pellets are soft: the soup will thicken slightly.", "Turn off the heat and let stand, covered, for 5 minutes.", "Finely chop the coriander, ladle the soup into bowls and sprinkle with herbs."], tip:"Add water to the flour a little at a time and rub with dry fingers: pour in too much at once and you get lumps of dough instead of pellets.", side:"Fresh flatbread", next:null, alt:{multi:"Onion, carrot, pepper and tomatoes on \"Fry\" for 12 minutes, then boiling water and potatoes on \"Soup\" for 15 minutes, pellets for the last 7 minutes."}},
  "x_tj_shirbirinj": {n:"Shirbirinj: Tajik milk rice pudding with raisins", how:["Rinse 120 g rice 3 times in cold water.", "Cover the rice with 250 ml water in a heavy-based pot and cook over medium heat for 10 minutes until the water is almost fully absorbed.", "While the rice cooks, rinse 30 g raisins and soak them in hot water for 10 minutes.", "Pour 600 ml milk over the rice, add a pinch of salt and bring to a boil, stirring constantly so the milk doesn't catch.", "Reduce to the lowest heat and simmer for 20-25 minutes, stirring every 3-4 minutes, until the rice breaks down and the porridge turns thick and creamy.", "Drain the raisins and pat dry on a towel.", "Add 30 g sugar, 2 tbsp, and the raisins to the porridge and cook 3 minutes more.", "Take off the heat, cover and leave for 5 minutes to thicken.", "Spoon into bowls and make a well in the centre of each with a spoon.", "Put 15 g butter into each well and serve warm while the butter melts over the surface."], tip:"Use round-grain rice for shirbirinj: it releases starch and makes the porridge thick and creamy, while long-grain rice stays as separate grains.", side:"Green tea", next:null, alt:{multi:"\"Milk porridge\" mode for 35 minutes: add rice, milk, 250 ml water and salt at the start, raisins and sugar 5 minutes before the end."}},
  "x_tj_ugro": {n:"Ugro: Tajik lamb soup with homemade noodles", how:["Cut 300 g lamb into 2 cm cubes, cover with 1.2 l cold water and bring to a boil over high heat.", "Skim off the foam, reduce to low heat and simmer for 50 minutes with the lid ajar.", "While the broth simmers, knead a stiff dough from 150 g flour, 1 egg, a pinch of salt and 2-3 tbsp water, cover and rest for 20 minutes.", "Roll the dough out very thin, 1-1.5 mm, and leave it to dry on the counter for 10 minutes.", "Roll the sheet up, cut into 3 mm wide noodles, fluff them apart and dust lightly with flour.", "Slice 120 g onion into half-rings, 100 g carrot into matchsticks, 80 g sweet pepper into strips and cut 200 g tomatoes into 1 cm dice.", "Heat 20 ml oil in a frying pan over medium heat and fry the onion for 4 minutes until golden.", "Add the carrot and pepper for 3 minutes, then the tomatoes, and cook for 5 minutes until soft.", "Add the vegetables to the broth with the meat, add 1 tsp cumin and salt and simmer for 10 minutes.", "Shake excess flour off the noodles, drop them into the boiling soup and cook for 4-5 minutes until they float and are tender.", "Take the soup off the heat and let stand, covered, for 5 minutes.", "Finely chop the coriander, ladle the soup into deep bowls and sprinkle with herbs."], tip:"Cut the noodles for ugro as thin as possible and dry them before cooking: that way they don't go mushy or cloud the broth.", side:"", next:null, alt:{pressure:"Cook the lamb for 20 minutes under pressure instead of 50 minutes on the stove, then follow the recipe.", multi:"Broth on \"Soup\" or \"Stew\" for 1 hour, then the vegetables and noodles on \"Boil\" for 15 minutes."}},
  "x_tw_eggplant_basil": {n:"Taiwanese eggplant with basil", how:["Rinse 180 g rice, add 360 ml water, bring to a boil and cook covered over low heat for 15 minutes.", "While the rice cooks, cut 500 g eggplant into batons 6 cm long and 1.5 cm thick so each keeps some skin.", "Finely chop 30 g garlic and 10 g ginger, and cut 50 g sweet pepper into thin strips.", "Pick the basil leaves off the stems.", "In a cup, stir 40 ml soy sauce, 2 tsp sugar, 10 ml vinegar and 2 tbsp water until the sugar dissolves.", "Heat 60 ml oil in a frying pan over high heat and lay the eggplant skin side down in a single layer.", "Fry for 5-6 minutes, turning, until soft with glossy skin; if they don't fit, fry in two batches.", "Push the eggplant to the side and fry the garlic, ginger and pepper in the free space for 30 seconds until fragrant.", "Pour in the sauce, stir and reduce over high heat for 1-2 minutes until it coats the pieces.", "Turn off the heat, add the basil leaves and toss for 10 seconds, just until they wilt.", "Fluff the rice with a fork and divide among bowls.", "Top with the eggplant and sauce and serve at once."], tip:"Add the basil after turning off the heat: its sharp aroma is the heart of this Taiwanese dish, and long cooking kills it.", side:"", next:{n:"Fried rice with eggplant and basil", how:["Cut the leftover eggplant into 2 cm pieces.", "Heat a frying pan over high heat with 1 tsp oil and fry the rice for 3 minutes.", "Add the eggplant with sauce and fry for 2 minutes, stirring.", "Sprinkle with soy sauce and serve hot."]}, alt:{wok:"In a wok over maximum heat the eggplant takes 4 minutes instead of 6.", airfryer:"Drizzle the eggplant with 2 tbsp oil, 200 °C, 12 minutes, shaking halfway, then reduce with the sauce in a frying pan for 2 minutes.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_tw_majiang_mian": {n:"Ma jiang mian: noodles in sesame sauce", how:["Put a large pot with 2 l water on the heat for the noodles.", "Toast 60 g sesame seeds in a dry frying pan over medium heat for 3-4 minutes, stirring, until golden and nutty.", "Tip the hot sesame into a blender, add 30 ml oil and blend for 1-2 minutes to a thick smooth paste.", "Finely grate 20 g garlic and add to the paste with 30 ml soy sauce, 20 ml vinegar and 2 tsp sugar.", "Blend 30 seconds more until smooth and transfer the sauce to a bowl.", "Cut 150 g cucumber into fine 3 mm matchsticks.", "Salt the boiling water and cook 200 g noodles according to the packet, usually 4-5 minutes.", "Before draining the noodles, reserve half a glass of the cooking water.", "Add the hot cooking water to the sauce 1 tbsp at a time, stirring, until it has the consistency of thin sour cream.", "Drain the noodles in a colander and divide among bowls.", "Top with the sauce and a pile of cucumber and toss just before eating."], tip:"Thin the sauce with hot noodle water: its starch makes the sesame paste silky and keeps it from seizing into lumps.", side:"", next:{n:"Cold noodles with sesame sauce", how:["Store the noodles and sauce separately in the fridge.", "Rinse the noodles under cold water to loosen them and shake off well.", "Thin the thickened sauce with 1-2 tbsp warm water.", "Toss the noodles with the sauce and fresh cucumber matchsticks."]}, alt:{micro:"You can toast the sesame in the microwave: 800 W, 2-3 minutes, stirring every 40 seconds."}},
  "x_tw_ma_you_ji": {n:"Ma you ji: sesame oil chicken with ginger", how:["Rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes, then leave covered.", "While the rice cooks, cut 600 g chicken thighs into 4 cm pieces with the skin on and pat dry with a towel.", "Scrub 60 g ginger well with a brush without peeling and slice 2 mm thick.", "Heat 40 ml oil in a deep frying pan over low heat, add 20 g sesame seeds and toast for 1-2 minutes until golden.", "Add the ginger and fry over low heat for 5-6 minutes until the edges are dry and slightly curled.", "Raise to medium heat, add the chicken and brown for 6-7 minutes until lightly golden on all sides.", "Meanwhile, bring 400 ml water to a boil.", "Pour in the hot water, add 20 ml soy sauce, 2 tsp sugar and salt.", "Cover and simmer over low heat for 20 minutes until the meat is tender and the juices run clear when pierced.", "Taste the broth and add salt if needed.", "Divide the rice among deep bowls, add the chicken and ginger and pour over the broth."], tip:"Fry the ginger slowly over low heat until dry: rush it and the sesame burns, making the dish bitter.", side:"", next:{n:"Chicken soup with rice and ginger", how:["If the thighs were bone-in, pull the meat off the bones.", "Add 300 ml water to the leftover broth and bring to a boil.", "Add the leftover rice and meat and simmer over low heat for 5 minutes.", "Salt to taste and ladle into bowls."]}, alt:{multi:"Sesame, ginger and chicken on \"Fry\" for 15 minutes, then water and sauce, \"Stew\" for 25 minutes.", pressure:"After browning, 8 minutes under pressure instead of 20 minutes of simmering."}},
  "x_tw_paigu_fan": {n:"Paigu fan: crispy Taiwanese pork chop rice", how:["Cut 350 g pork across the grain into 1 cm thick chops.", "Pound the meat through cling film to 5-6 mm and nick the edges in 2-3 places so it doesn't curl.", "Crush and finely chop 20 g garlic and mix with 40 ml soy sauce, 2 tsp sugar, mixed pepper and 1 tbsp water.", "Pour the marinade over the meat, toss and leave for 20 minutes.", "While the meat marinates, rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes.", "Cut 200 g cabbage into 4 cm squares.", "Heat 1 tbsp oil in a frying pan over high heat and stir-fry the cabbage with a pinch of salt for 3-4 minutes until tender but still crunchy, then transfer to a bowl.", "Crack the egg into the marinated meat and mix by hand so the marinade thickens and clings to the pieces.", "Dredge each chop in 60 g flour, pressing firmly, and leave for 5 minutes until the coating turns slightly damp.", "Pour the remaining oil into the pan and heat over medium heat to 170 °C.", "Fry the chops for 2-3 minutes per side until deep golden and crisp.", "Drain on paper towels for 2 minutes and cut into 2 cm strips.", "Divide the rice among plates, lay a chop on top and the cabbage alongside."], tip:"Let the coated meat rest for 5 minutes before frying: the flour absorbs the marinade and the crust won't peel off in the oil.", side:"", next:{n:"Fried rice with pork and cabbage", how:["Cut the leftover chop into 1 cm pieces.", "Heat a frying pan over high heat with 1 tbsp oil and fry the rice for 3 minutes.", "Add the cabbage and pork and fry 3 minutes more.", "Crack in an egg, stir quickly until set and sprinkle with soy sauce."]}, alt:{airfryer:"Drizzle the coated chops with 2 tbsp oil, 200 °C, 12-14 minutes, turning at minute 7.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_th_pad_krapao": {n:"Pad kra pao: Thai basil chicken with fried egg", how:["Rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes.", "While the rice cooks, chop 350 g chicken fillet with a knife into 3-5 mm bits, like coarse mince.", "Pound 30 g garlic in a mortar or chop finely, and finely dice 50 g sweet pepper.", "Pick the basil leaves off the stems.", "In a cup, mix 20 ml soy sauce, 1 tbsp fish sauce, 2 tsp sugar and 2 tbsp water.", "Heat 5 tbsp oil in a frying pan over high heat and crack in 2 eggs.", "Fry for 2 minutes, basting the whites with hot oil, until the edges are crisp and lacy and the yolks runny, then transfer to a plate.", "Pour off excess oil, leaving 1 tbsp, and fry the garlic and pepper for 20 seconds without letting them burn.", "Add the chicken and fry over maximum heat for 3-4 minutes, breaking up clumps, until white.", "Pour in the sauce and reduce for 1 minute to a light gloss.", "Turn off the heat and stir in the basil leaves.", "Divide the rice among plates, add the chicken alongside and top with the fried egg."], tip:"Fry the egg for kra pao in plenty of hot oil: that is the only way to get the crisp lacy edge the dish is made for.", side:"", next:{n:"Kra pao wrapped in a thin omelette", how:["Reheat the leftover chicken in a frying pan for 2-3 minutes and transfer to a bowl.", "Beat 2 eggs and pour in a thin layer into the pan with 1 tsp oil.", "Cook over medium heat for 1-2 minutes until set.", "Spoon the chicken onto half the omelette, fold over the other half and serve with rice."]}, alt:{wok:"In a very hot wok the chicken takes 2-3 minutes, everything else stays the same.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_th_tom_yum_kung": {n:"Tom yum goong with shrimp", how:["If the shrimp are frozen, thaw them in the fridge or in a bowl of cold water for 15 minutes.", "Peel 300 g shrimp, leaving the tails on, and put the shells and heads in a pot.", "Cover the shells with 800 ml water, bring to a boil and simmer over medium heat for 10 minutes.", "While the stock simmers, slice 30 g ginger into thin coins, cut 80 g onion into wedges, 150 g tomatoes into 6 wedges and halve or quarter 150 g mushrooms.", "Cut 30 g sweet pepper into thin strips and separate the coriander stems from the leaves.", "Strain the stock through a sieve, discard the shells and return the stock to the pot.", "Add the ginger, coriander stems and pepper and simmer over low heat for 5 minutes for aroma.", "Add the mushrooms, onion and tomatoes and cook for 3 minutes.", "Add the shrimp and cook for 2 minutes until pink and curled.", "Squeeze the juice from 2 limes.", "Take the soup off the heat and add 2 tbsp fish sauce, 2 tsp sugar and the lime juice.", "Taste: it should be sour and salty at once; add more lime or fish sauce if needed.", "Ladle into bowls and sprinkle with coriander leaves."], tip:"Add the lime juice only after taking the pot off the heat: boiling makes it bitter and dulls its freshness.", side:"A bowl of hot rice", next:null, alt:{}},
  "x_th_pad_pak_ruam": {n:"Pad pak ruam: Thai garlic stir-fried vegetables", how:["Rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes.", "While the rice cooks, take 200 g broccoli out of the freezer for 10 minutes, then pat dry with a towel.", "Break the broccoli into 3 cm florets and cut 150 g cabbage into 4 cm squares.", "Slice 100 g carrot thinly on the diagonal, 100 g sweet pepper into strips and 150 g mushrooms into slices.", "Crush and roughly chop 30 g garlic.", "In a cup, mix 40 ml soy sauce, 2 tsp sugar and 50 ml water.", "Heat a wok or large frying pan over maximum heat until it just smokes, add 30 ml oil and fry the garlic for 15 seconds until golden.", "Add the carrot and broccoli and stir-fry for 2 minutes, tossing constantly.", "Add the cabbage, pepper and mushrooms and stir-fry 2 minutes more.", "Pour in the sauce and cover for 1 minute so the broccoli steams through.", "Uncover and toss: the vegetables should stay crisp and bright.", "Divide the rice among plates and immediately top with the vegetables and sauce."], tip:"The wok must be smoking hot and the vegetables dry, otherwise they stew in their own juices instead of searing quickly.", side:"", next:{n:"Vegetable fried rice", how:["Heat a frying pan over high heat with 1 tsp oil.", "Add the leftover rice and fry for 3 minutes, breaking up any clumps.", "Add the leftover vegetables with sauce and fry for 2-3 minutes, stirring.", "Sprinkle with soy sauce and serve hot."]}, alt:{wok:"In a wok over maximum heat the timing is the same, and the vegetables pick up a light smoky aroma.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_th_khai_jiao": {n:"Khai jiao: puffy Thai omelette with rice", how:["Rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes.", "While the rice cooks, dice 50 g onion very finely, slice 100 g cucumber into 5 mm rounds and cut the lime into wedges.", "Crack 4 eggs into a bowl and add 20 ml soy sauce, 10 g flour, a level tablespoon, the onion and the juice of one lime wedge.", "Beat with a fork for 1 minute until frothy and free of flour lumps.", "Line a plate with paper towels for the finished omelette.", "Pour 150 ml oil into a deep frying pan or wok and heat over high heat to 180 °C, until a drop of egg bubbles instantly.", "Pour the eggs from a height of 20 cm in one stream into the centre of the oil: the omelette will instantly foam and puff up.", "Fry for 1-2 minutes until the underside is golden brown and the edges are lacy.", "Flip the omelette with a wide spatula and fry the other side for 1 minute.", "Drain on paper towels for 30 seconds.", "Divide the rice among plates, top with the omelette, add the cucumber and lime wedges alongside and serve with ketchup."], tip:"You need plenty of oil and it must be very hot: eggs poured from a height burst into bubbles and give that signature puffy, crisp omelette.", side:"", next:null, alt:{wok:"In a wok the oil pools in the centre, so the omelette puffs higher; frying time is the same.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_tn_mechouia": {n:"Slata mechouia: Tunisian roasted pepper salad", how:["Preheat the oven to 230 °C.", "Wash and dry 500 g peppers and 300 g tomatoes, leave 100 g onion in its skin and separate 20 g garlic into unpeeled cloves.", "Spread everything on a baking tray in a single layer and roast for 25-30 minutes, turning every 10 minutes, until the pepper skins blister and char in patches.", "Transfer the hot peppers to a bowl and cover tightly with a plate for 10 minutes so the steam loosens the skins.", "While the peppers rest, toast 1 tsp cumin in a dry frying pan over medium heat for 30 seconds and grind it.", "Peel and seed the peppers and skin the tomatoes.", "Squeeze the onion and garlic out of their skins.", "Chop all the vegetables with a knife on a board into 5 mm pieces without turning them into a purée.", "Squeeze the juice of half a lemon.", "Mix the vegetables with the cumin, salt, lemon juice and 30 ml olive oil and leave for 10 minutes for the flavours to come together.", "Drain the olives from the jar.", "Spread the mechouia on a flat plate, make grooves with a spoon, drizzle with the remaining oil and garnish with olives.", "Serve warm or at room temperature with slices of bread."], tip:"Roast the peppers until they have real black patches: the smoky flavour of charred skin is what makes mechouia, and pale peppers just give you a vegetable salad.", side:"", next:{n:"Toasts with mechouia and olives", how:["Slice the bread and toast in a dry frying pan for 1-2 minutes per side.", "Spread the cold mechouia thickly on the toasts.", "Garnish with halved olives and drizzle with olive oil."]}, alt:{airfryer:"Peppers, tomatoes, onion and garlic: 200 °C, 18-20 minutes, turning halfway, in two batches if needed."}},
  "x_tn_kafteji": {n:"Kafteji: Tunisian chopped fried vegetables with egg", how:["Peel 300 g potatoes, 200 g pumpkin and 150 g zucchini and cut into 2 cm cubes.", "Seed 200 g peppers and cut into quarters, and score a cross in 200 g tomatoes.", "Line a large plate with paper towels.", "Heat 250 ml oil in a deep frying pan over medium heat to 170 °C.", "Fry the potatoes for 8-10 minutes until tender with golden edges and drain on the towels.", "In the same oil fry the pumpkin for 5 minutes, then the zucchini for 4 minutes, draining each on the towels.", "Fry the peppers for 3 minutes, then the tomatoes for 2 minutes, and peel the tomatoes.", "While the vegetables fry, pound 20 g garlic with 1 tsp paprika, 1/2 tsp cumin, salt and 1 tbsp oil into a spicy paste.", "Crack 2 eggs into the hot oil and fry for 3-4 minutes until the yolks are fully set.", "Pile all the vegetables, tomatoes and eggs on a large board and chop criss-cross with a wide knife into 1 cm pieces.", "Add the garlic paste, mix and taste for salt.", "Mound on a plate and serve warm with bread."], tip:"Each vegetable is fried separately because they cook at different speeds, and everything is chopped only at the very end so the kafteji doesn't turn to mush.", side:"", next:{n:"Kafteji with eggs for breakfast", how:["Reheat the leftover kafteji in a frying pan with 1 tsp oil for 3 minutes.", "Make 2 wells in the vegetables and crack an egg into each.", "Salt, cover and cook over low heat for 4-5 minutes until the whites set.", "Serve with a slice of bread."]}, alt:{airfryer:"Instead of deep-frying: drizzle the cubes with 2 tbsp oil, potatoes at 200 °C for 18 minutes, pumpkin, zucchini and peppers together at 200 °C for 12 minutes."}},
  "x_tn_tajine_djej": {n:"Tunisian tajine with chicken and cheese (baked egg dish)", how:["Cut 300 g chicken fillet into 1.5 cm cubes and finely dice 100 g onion.", "Heat 15 ml oil in a saucepan over medium heat and fry the onion for 3 minutes until translucent.", "Add the chicken, 1 tsp turmeric, salt and mixed pepper and fry for 5 minutes, stirring.", "Pour in 150 ml water, cover and simmer over low heat for 15 minutes until the meat is tender.", "While the chicken simmers, peel 200 g potatoes and cut into 1 cm cubes.", "Fry the potatoes in a frying pan in 10 ml oil over medium heat for 10 minutes until tender.", "Uncover the chicken, boil off the liquid over high heat for 2-3 minutes and let cool for 10 minutes.", "Preheat the oven to 180 °C and grease a 20 x 20 cm dish with the remaining oil.", "Coarsely grate 100 g cheese, finely chop the parsley and crumble the soft inside of one slice of bread.", "Beat 5 eggs with a pinch of salt and combine with the chicken, potatoes, cheese, parsley and breadcrumbs.", "Pour the mixture into the dish, level it and bake for 25-30 minutes until the centre is springy and the top golden.", "Let cool for 10 minutes, cut into 5 cm squares and serve warm or cold."], tip:"Cool the chicken before adding it to the eggs, otherwise the hot meat cooks the whites and the tajine turns grainy.", side:"Tomato and cucumber salad", next:{n:"Hot tajine sandwich", how:["Cut the cold tajine into slabs 1.5 cm thick.", "Toast slices of bread in a dry frying pan for 1 minute per side.", "Put the tajine between the slices and warm, covered, over low heat for 2-3 minutes.", "Cut in half and serve."]}, alt:{airfryer:"Dish up to 18 cm: 160 °C, 25 minutes, test the centre with a toothpick.", multi:"Pour the mixture into the greased bowl, \"Bake\" mode for 40 minutes instead of the oven."}},
  "x_tn_jelbana": {n:"Jelbana: Tunisian pea and lamb stew", how:["Cut 300 g lamb into 3 cm pieces and pat dry with a towel.", "Finely dice 100 g onion and crush 20 g garlic with a knife.", "Heat 30 ml oil in a heavy-based pot over high heat and brown the meat for 5-6 minutes.", "Add the onion and cook over medium heat for 4 minutes until soft, then the garlic for 30 seconds.", "Stir in 40 g tomato paste, 2 tbsp, 1 tsp paprika and 1/2 tsp cumin and cook for 1 minute until the paste darkens.", "Pour in 500 ml hot water, salt, cover and simmer over low heat for 35 minutes.", "While the meat simmers, peel 200 g potatoes and cut into 2 cm cubes.", "Add the potatoes to the meat and simmer 12 minutes more until tender.", "Drain the peas in a sieve and rinse with cold water.", "Add the peas to the stew for the last 5 minutes so they heat through without going mushy.", "If the sauce is thin, uncover and reduce for 3 minutes to a creamy consistency.", "Serve in deep plates with bread."], tip:"Always fry the tomato paste and spices in the oil until they darken: this cooks off the acidity and gives the sauce its rich Tunisian flavour.", side:"", next:{n:"Thick jelbana soup with croutons", how:["Transfer the leftover stew to a pot and add 400 ml water.", "Bring to a boil, simmer for 5 minutes and salt to taste.", "Cut bread into cubes and toast in a dry frying pan for 4 minutes.", "Ladle the soup into bowls and top with the croutons."]}, alt:{multi:"Browning on \"Fry\" for 15 minutes, then \"Stew\" for 50 minutes, potatoes after 35 minutes, peas for the last 5 minutes.", pressure:"After browning, the meat for 15 minutes under pressure, then the potatoes without pressure for 12 minutes."}},
  "x_tr_imam_bayildi": {n:"Imam bayildi: Turkish stuffed eggplant", how:["Wash 600 g eggplant and peel off lengthwise strips of skin to leave 1.5 cm wide zebra stripes.", "Sprinkle the eggplant with salt and leave for 20 minutes, then rinse and pat dry with a towel.", "Meanwhile, slice 200 g onion into thin half-rings, 30 g garlic into thin slices, dice 300 g tomatoes into 1 cm cubes and finely chop the parsley.", "Heat 40 ml olive oil in a frying pan over medium heat and fry the whole eggplants for 8-10 minutes, turning, until soft and golden, then transfer to a baking dish.", "In the remaining oil cook the onion over medium heat for 8 minutes until soft and sweet.", "Add the garlic and cook for 1 minute.", "Add two thirds of the tomatoes, 2 tsp sugar and salt and cook for 5 minutes.", "Turn off the heat, stir in half the parsley and preheat the oven to 180 °C.", "Cut a deep lengthwise slit in each eggplant without cutting through the bottom and spread it open with a spoon into a boat.", "Pack the eggplants tightly with the onion filling and top with the remaining tomatoes.", "Pour 100 ml hot water into the dish and bake for 30 minutes until the eggplants collapse and are completely soft.", "Cool to room temperature and sprinkle with the remaining parsley."], tip:"Use plenty of onion and cook it slowly until sweet: that sweet, olive oil-soaked onion filling is the whole point of the dish.", side:"Flatbread or bread", next:{n:"Cold chopped imam bayildi salad", how:["Cut the cold stuffed eggplant into 2 cm pieces.", "Drizzle with 1 tbsp olive oil and toss.", "Sprinkle with chopped parsley and serve chilled."]}, alt:{airfryer:"Baking the stuffed eggplant in a dish: 170 °C, 20-25 minutes, add 50 ml water."}},
  "x_tr_kisir": {n:"Kisir: spicy Turkish bulgur salad", how:["Rinse 150 g fine bulgur in a sieve under cold water.", "Bring 180 ml water to a boil, pour it over the bulgur, cover with a plate and leave for 15 minutes until fully absorbed.", "While the bulgur swells, cut 200 g tomatoes and 150 g cucumber into fine 5 mm dice.", "Chop 50 g onion very finely.", "Finely chop the parsley and mint and squeeze the lemon juice.", "Seed 150 g pomegranate over a bowl to catch the juice.", "Add 30 g tomato paste, 1 tsp paprika, 1/2 tsp cumin and salt to the warm bulgur.", "Mix with your hands, rubbing so the grains turn evenly red.", "Add the vegetables, herbs, lemon and pomegranate juice and 40 ml olive oil and mix.", "Leave for 10 minutes, then taste for salt and acidity.", "Mound on a platter and sprinkle with the remaining pomegranate seeds."], tip:"Rub the tomato paste into the still-warm bulgur by hand: the grains absorb it evenly and the kisir turns bright red instead of patchy.", side:"", next:null, alt:{}},
  "x_tr_cilbir": {n:"Çılbır: Turkish poached eggs on garlic yogurt", how:["Take 300 g yogurt out of the fridge 30 minutes ahead so it comes to room temperature.", "Finely grate 20 g garlic and mix into the yogurt with a pinch of salt.", "Finely chop the dill and stir half into the yogurt.", "Spread the yogurt over two plates in a wide layer.", "Bring 1.5 l water to a boil in a saucepan, add 20 ml vinegar and lower the heat to the barest simmer.", "Crack each of the 4 eggs into a separate cup.", "Swirl the water with a spoon into a whirlpool, gently tip an egg into the centre and poach for 3 minutes until the white is set and the yolk still runny.", "Lift the egg out with a slotted spoon onto a towel and repeat with the rest, poaching 1-2 at a time.", "Slice the bread and toast in a dry frying pan for 1 minute per side.", "Melt 40 g butter in a frying pan over low heat until it smells lightly nutty.", "Take off the heat and stir in 1 tsp paprika so the butter turns red without burning.", "Place 2 eggs on each yogurt plate, drizzle with the paprika butter, sprinkle with the remaining dill and serve with bread."], tip:"The yogurt must be at room temperature: cold yogurt chills the eggs, and the hot butter sets instantly on icy yogurt.", side:"", next:null, alt:{micro:"Paprika butter: melt in the microwave for 30-40 seconds at 800 W and stir in the paprika right away."}},
  "x_tr_kuru_fasulye": {n:"Etli kuru fasulye: Turkish white beans with beef and rice", how:["Cut 250 g beef into 1.5 cm cubes and pat dry with a towel.", "Finely dice 120 g onion, cut 80 g pepper into 1 cm dice and grate 150 g tomatoes, discarding the skin.", "Heat 20 ml oil in a pot over high heat and brown the beef for 5 minutes.", "Add the onion and pepper and cook over medium heat for 5 minutes until soft.", "Stir in 40 g tomato paste and 1 tsp paprika, cook for 1 minute and add the grated tomato.", "Pour in 400 ml hot water, salt, cover and simmer over low heat for 30 minutes until the meat is tender.", "When the meat has simmered for 20 minutes, rinse 150 g rice and fry it in a saucepan in 20 g butter for 2 minutes.", "Pour 300 ml salted boiling water over the rice and cook covered over low heat for 15 minutes.", "Meanwhile, drain 2 cans of beans in a colander and rinse.", "Add the beans to the meat and simmer 10 minutes more until the sauce thickens, stirring only occasionally.", "Take the rice off the heat and leave covered, with a towel over the lid, for 5 minutes.", "Serve the beans with sauce and the rice on plates."], tip:"Add the canned beans at the end and stir rarely: that way they soak up the sauce without breaking down into mush.", side:"", next:{n:"Bean soup with rice", how:["Transfer the leftover beans and sauce to a pot and add 400 ml water.", "Bring to a boil and add the leftover rice.", "Simmer for 5 minutes, salt and sprinkle with a pinch of paprika."]}, alt:{multi:"Meat with sauce on \"Stew\" for 40 minutes, beans for the last 10 minutes.", pressure:"Meat with water for 12 minutes under pressure instead of 30 minutes of simmering, then the beans without pressure for 10 minutes."}},
  "x_tm_unash": {n:"Unash: Turkmen noodle soup with beans and yogurt", how:["Mix 150 g flour with a pinch of salt, pour in 70 ml water and make a stiff dough; knead for 5 minutes, cover and rest for 20 minutes.", "While the dough rests, finely dice 100 g onion and coarsely grate 80 g carrot.", "Drain the beans in a colander and rinse.", "Roll the dough out 2 mm thick and let it dry for 5 minutes.", "Roll the sheet up, cut into 4 mm wide noodles and fluff them apart.", "Heat 30 ml oil in a pot over medium heat and fry the onion for 4 minutes, then add the carrot for 3 minutes.", "Stir in 30 g tomato paste and cook for 1 minute until it darkens.", "Pour in 1 l hot water, add the beans, salt and mixed pepper and simmer for 10 minutes.", "Shake the flour off the noodles, drop them into the soup and cook for 6-7 minutes until tender.", "Turn off the heat, let stand for 5 minutes and finely chop the dill.", "Ladle into bowls, add 3-4 tbsp yogurt to each and sprinkle with dill."], tip:"Spoon the yogurt straight into the hot soup just before serving and don't stir it in right away: a cool spoonful of tangy yogurt next to hot noodles is what gives unash its flavour.", side:"", next:null, alt:{multi:"Onion and carrot on \"Fry\" for 8 minutes, then water and beans on \"Soup\" for 10 minutes, noodles for 8 minutes more."}},
  "x_tm_gowurdak": {n:"Gowurdak: Turkmen fried lamb with onion and potatoes", how:["Cut 400 g lamb into 2 cm cubes and pat dry with a towel.", "Heat 4 tbsp oil in a kazan or heavy frying pan over high heat and add the meat in a single layer.", "Fry for 8 minutes, leaving it untouched for the first 3 minutes, then stirring, until deeply browned.", "Salt, add 1 tsp cumin and mixed pepper, reduce to low heat, cover and cook for 20 minutes until the liquid has almost evaporated.", "While the meat cooks, cut 200 g onion into thick half-rings, 80 g pepper into strips and 150 g tomatoes into wedges.", "Peel 350 g potatoes, cut into 1.5 x 5 cm batons and pat dry.", "In a separate frying pan heat the remaining oil over medium heat and fry the potatoes for 12-15 minutes until golden and tender, then salt.", "Add the onion to the meat and fry uncovered over medium heat for 6 minutes until golden.", "Add the pepper and tomatoes and fry for 5 minutes until soft.", "Combine the meat with the potatoes, stir and heat together for 3 minutes.", "Finely chop the coriander, pile the gowurdak on a platter and sprinkle with herbs."], tip:"Fry the meat for gowurdak in a single layer and in small batches: in an overcrowded kazan the lamb stews instead of browning.", side:"Fresh tomatoes", next:{n:"Crispy-bottomed gowurdak", how:["Heat a frying pan over medium heat without oil.", "Add the leftovers in a tight layer and press down with a spatula.", "Fry for 5 minutes without stirring until a crust forms underneath.", "Turn over in large pieces, heat for 2 minutes and sprinkle with coriander."]}, alt:{airfryer:"Potato batons: drizzle with 1 tbsp oil, 200 °C, 18-20 minutes, shaking every 6 minutes."}},
  "x_tm_shule": {n:"Shule: thick Turkmen rice soup with lamb", how:["Cut 250 g lamb into 1.5 cm cubes.", "Slice 100 g onion into half-rings, 100 g carrot into matchsticks and dice 150 g tomatoes into 1 cm cubes.", "Heat 30 ml oil in a heavy-based pot over high heat and brown the meat for 6 minutes.", "Add the onion and carrot and cook over medium heat 5 minutes more until soft.", "Add the tomatoes, 1 tsp cumin and mixed pepper and cook for 5 minutes.", "Pour in 1 l hot water, salt, cover and simmer over low heat for 25 minutes.", "While the meat simmers, rinse 150 g rice in several changes of water.", "Add the rice to the pot and simmer over low heat for 20 minutes, scraping the bottom every 5 minutes so it doesn't catch.", "Check the thickness: the rice should be completely broken down and the soup thick but pourable; add boiling water if needed.", "Take off the heat and leave covered for 5 minutes.", "Finely chop the dill, ladle the shule into deep plates and sprinkle with herbs."], tip:"Cook shule over low heat and stir often from the bottom: the soft rice releases starch and catches on the pot easily.", side:"", next:null, alt:{multi:"Browning on \"Fry\" for 15 minutes, then water on \"Stew\" for 30 minutes and the rice for 25 minutes more.", pressure:"Meat with water for 15 minutes under pressure, then the rice for 8 minutes under pressure with natural release."}},
  "x_tm_pishme": {n:"Pishme: Turkmen fried dough with honey", how:["Melt 30 g butter over low heat and let cool until warm.", "Mix the butter with 120 ml warm milk, 1 egg, 30 g sugar and a pinch of salt.", "Gradually add 300 g flour and knead a soft dough that doesn't stick to your hands.", "Knead for 5 minutes until smooth, cover with cling film and rest for 20 minutes.", "Roll the dough out 5 mm thick.", "Cut into 4 cm wide strips with a knife, then diagonally into diamonds.", "Cut a 2 cm slit in the centre of each diamond.", "Heat 300 ml oil in a deep frying pan over medium heat to 170 °C: a scrap of dough should rise at once surrounded by bubbles.", "Fry the pishme 6-8 at a time for 2-3 minutes, turning, until evenly golden.", "Drain on paper towels to remove excess oil.", "Warm 40 g honey for 15 seconds in the microwave or over a water bath until runny.", "Serve the pishme warm with the honey."], tip:"Don't overheat the oil: if it is too hot, pishme darken outside within a minute and stay raw inside.", side:"Green tea", next:null, alt:{deepfryer:"In a deep fryer at 170 °C in batches for 2-3 minutes instead of a frying pan.", airfryer:"Brush the diamonds with oil, 180 °C, 8-10 minutes, turning halfway; the pishme will be denser."}},
  "x_uz_shurpa": {n:"Shurpa: Uzbek lamb soup", how:["Cut 450 g lamb into 5-6 cm pieces and rinse.", "Cover the meat with 2 l cold water in a large pot and slowly bring to a boil over medium heat.", "Skim off the foam with a slotted spoon for 5-7 minutes until the broth is clear.", "Reduce the heat to the barest simmer, add half the onion as a whole bulb and simmer for 60 minutes.", "While the broth simmers, cut 150 g carrot into large batons, 100 g pepper into quarters and 200 g tomatoes into 4 wedges.", "Peel 300 g potatoes, halve them and keep in cold water until needed.", "Remove the soft onion from the broth, add the carrot and simmer for 15 minutes.", "Add the potatoes, pepper, 1 tsp cumin, 2 bay leaves, salt and mixed pepper and simmer for 15 minutes.", "Add the tomatoes and simmer 7 minutes more until the potatoes are tender.", "Turn off the heat and let the shurpa infuse, covered, for 10 minutes.", "Meanwhile, finely chop the coriander and slice the remaining onion into thin rings.", "Divide the meat and large vegetables among bowls, pour over the hot broth and sprinkle with coriander and onion rings."], tip:"Never boil shurpa hard: over high heat the broth turns cloudy, and Uzbek shurpa should be as clear as tea.", side:"Fresh flatbread", next:null, alt:{pressure:"Meat with the onion for 25 minutes under pressure instead of an hour, then the vegetables without pressure as in the recipe.", multi:"\"Soup\" or \"Stew\" mode: meat for 1.5 hours, vegetables 30 minutes before the end."}},
  "x_uz_dimlama": {n:"Dimlama: Uzbek meat and vegetables braised in their own juices", how:["Cut 400 g beef into 4 cm pieces and pat dry with a towel.", "Slice 200 g onion into rings, 150 g carrot into 1 cm rounds and halve 300 g potatoes.", "Cut 200 g eggplant and 150 g pepper into large chunks and slice 250 g tomatoes into rounds.", "Peel 3-4 whole leaves off 300 g cabbage to cover the dish and cut the rest into large squares.", "Heat 30 ml oil in a kazan over high heat and brown the meat for 6 minutes, then salt and sprinkle with 1 tsp cumin.", "Take the kazan off the heat and layer the onion, carrot and potatoes over the meat without stirring, lightly salting each layer.", "Top with the chopped cabbage, eggplant, pepper and tomatoes, also salting.", "Tuck unpeeled garlic cloves, 30 g in total, and basil sprigs between the layers.", "Cover everything with the whole cabbage leaves and close the lid tightly; don't add water.", "Return the kazan to the lowest heat and braise for 70-80 minutes without lifting the lid.", "Test the potatoes with a knife: it should slide in easily, then turn off the heat and leave for 10 minutes.", "Remove the cabbage leaves, divide the meat and vegetables among deep plates and spoon over the juices from the bottom of the kazan."], tip:"The lid must fit tightly, wrap it in a towel if needed: all the flavour of dimlama is in the steam and juices, which must not escape.", side:"Flatbread", next:{n:"Soup from leftover dimlama", how:["Transfer the leftovers with their juices to a pot and add 500 ml water.", "Cut the large pieces of meat and potato smaller.", "Bring to a boil, simmer for 5 minutes and salt to taste."]}, alt:{multi:"Layers in the bowl, \"Stew\" mode for 1.5 hours, don't open the lid.", pressure:"25 minutes under pressure with natural release; add 50 ml water so it can build pressure."}},
  "x_uz_tukhum_barak": {n:"Tukhum barak: Khorezm dumplings filled with egg", how:["Mix 200 g flour with a pinch of salt, pour in 100 ml water and make a stiff dough.", "Knead for 7 minutes until smooth, cover with cling film and rest for 20 minutes.", "While the dough rests, beat 4 eggs with 120 ml milk, salt and mixed pepper until smooth but not frothy, and pour into a jug with a spout.", "Roll the dough into a thin 1.5 mm sheet and cut into 8 x 8 cm squares.", "Fold each square in half and press the two sides firmly together, leaving the top open, to make a pocket.", "Holding the pocket upright, pour in 1.5-2 tbsp egg mixture and immediately pinch the top edge shut with no gaps.", "Place the finished barak on a floured tray so they don't touch.", "Bring 3 l salted water to a boil in a large pot over high heat.", "Drop the barak in one at a time, gently stirring the water so they don't stick to the bottom.", "Cook for 5-6 minutes after they float, until the egg inside sets.", "Meanwhile, melt 30 g butter.", "Lift the barak into a bowl with a slotted spoon, immediately pour over the butter and shake so they don't stick together.", "Serve hot with 100 g sour cream."], tip:"Keep the pocket edges dry before filling: if egg mixture gets on them, the seam will open in the boiling water.", side:"", next:{n:"Pan-fried crispy barak", how:["Heat a frying pan with 1 tsp butter over medium heat.", "Lay the cooled barak in a single layer and fry for 2-3 minutes per side until golden.", "Serve hot with sour cream."]}, alt:{}},
  "x_uz_khanum": {n:"Khanum: Uzbek steamed potato roll with tomato sauce", how:["Mix 250 g flour with a pinch of salt, pour in 120 ml warm water and 1 tbsp oil and knead an elastic dough.", "Cover the dough and rest for 30 minutes.", "While the dough rests, peel 400 g potatoes and cut into very fine 5 mm dice, and dice 200 g onion the same way.", "Mix the potatoes and onion with 1 tsp cumin, salt, mixed pepper and 2 tbsp oil.", "Fill a steamer or manti steamer with water and start heating it.", "Roll the dough into a thin 2 mm sheet about 35 x 45 cm.", "Brush the sheet with a thin layer of oil and spread the filling evenly, leaving a 2 cm border.", "Roll up tightly and pinch the ends closed.", "Grease the steamer rack with oil and coil the roll on it in a spiral.", "Steam for 40-45 minutes until the potatoes in the filling are soft and the dough is translucent.", "While the khanum steams, grate 200 g tomatoes, discarding the skin, and crush 20 g garlic.", "Cook the tomatoes and garlic in the remaining oil in a saucepan over medium heat for 5 minutes to a thick sauce, then salt.", "Cut the khanum into 5 cm pieces and serve with the tomato garlic sauce."], tip:"Dice the potatoes for the filling rather than grating them: grated potato releases water and makes the dough soggy, while dice stay juicy.", side:"", next:{n:"Pan-fried khanum with tomato sauce", how:["Cut the cold khanum into 2 cm thick pieces.", "Fry in a frying pan with 1 tbsp oil over medium heat for 2-3 minutes per side until crisp.", "Warm the leftover sauce and pour over the khanum."]}, alt:{multi:"\"Steam\" mode for 45 minutes on the greased multicooker rack instead of a steamer."}},
  "x_ua_banosh": {n:"Banosh: Hutsul cornmeal porridge with bryndza and mushrooms", how:["Slice 250 g mushrooms 5 mm thick and finely dice 80 g onion.", "Crumble 120 g bryndza by hand or coarsely grate it.", "In a heavy saucepan combine 200 g sour cream, 100 ml cream and 300 ml water, salt and bring to a boil over medium heat.", "Pour in 150 g cornmeal in a thin stream, stirring constantly in one direction with a wooden spatula.", "Reduce to low heat and cook for 20-25 minutes, stirring constantly, until the porridge thickens and beads of butter appear on the surface.", "Meanwhile, without forgetting to stir the porridge, melt 30 g butter in a frying pan over medium heat.", "Fry the onion for 3 minutes until translucent.", "Add the mushrooms and fry over high heat for 8-10 minutes until the liquid evaporates and they brown, then salt.", "Take the banosh off the heat and let stand for 2 minutes.", "Spoon onto warm plates and top with the mushrooms and onion.", "Sprinkle generously with bryndza and serve at once."], tip:"Hutsul banosh is stirred in one direction without stopping: this draws butterfat out of the sour cream and makes the porridge smooth and glossy.", side:"", next:{n:"Fried banosh slices with bryndza", how:["Spread the leftover banosh in a dish 2 cm thick and refrigerate overnight.", "Cut the set porridge into bars.", "Fry in butter over medium heat for 3 minutes per side until crisp.", "Sprinkle with bryndza and serve with the leftover mushrooms."]}, alt:{multi:"Banosh: \"Porridge\" or \"Milk porridge\" mode for 30 minutes, stirring 2-3 times."}},
  "x_ua_hrybna_yushka": {n:"Hrybna yushka: Carpathian mushroom soup", how:["Slice 300 g mushrooms 5 mm thick.", "Peel and cut 300 g potatoes into 1.5 cm cubes, 100 g carrot into matchsticks and finely dice 100 g onion.", "Bring 1.2 l water to a boil in a pot, add the mushrooms and simmer over medium heat for 15 minutes, skimming off the foam.", "Add the potatoes, 2 bay leaves and salt and simmer for 10 minutes.", "While the potatoes cook, heat 30 ml oil in a frying pan over medium heat and fry the onion for 3 minutes.", "Add the carrot and fry 4 minutes more until soft.", "Sprinkle 20 g flour over the vegetables and stir for 1 minute until nutty brown.", "Add the fried vegetables to the soup, stir so there are no lumps and simmer for 5 minutes until lightly thickened.", "Crush 20 g garlic and finely chop the dill and parsley.", "Add the garlic, half the herbs and mixed pepper to the soup and turn off the heat.", "Let infuse, covered, for 10 minutes and remove the bay leaves.", "Ladle into plates and sprinkle with the remaining herbs."], tip:"Toast the flour until nutty brown rather than just warming it: it gives yushka a light body and mushroom aroma without any sour cream.", side:"Rye bread", next:null, alt:{multi:"Mushrooms and potatoes on \"Soup\" for 25 minutes, add the pan-fried vegetables for the last 5 minutes."}},
  "x_ua_nalysnyky": {n:"Nalysnyky: Ukrainian crêpes with tvorog baked in sour cream", how:["Beat 1 egg with 20 g sugar and a pinch of salt and pour in 300 ml milk.", "Gradually add 120 g flour, whisking to a smooth thin batter, add 20 ml oil and rest for 15 minutes.", "While the batter rests, soak 30 g raisins in boiling water for 10 minutes, then pat dry.", "Mash 350 g tvorog with a fork, add the second egg, the remaining 20 g sugar and the raisins and mix.", "Heat a 20 cm frying pan over medium heat.", "Pour in a ladle of batter at a time, swirling into a thin layer, and cook for 1 minute per side until lightly golden in spots.", "Preheat the oven to 180 °C and grease a baking dish with 10 g butter.", "Put 2 tbsp filling near the edge of each crêpe, fold in the sides and roll up.", "Pack the nalysnyky tightly in the dish, seam side down.", "Pour over 150 g sour cream and dot with the remaining 30 g butter.", "Bake for 20 minutes until the sour cream sets and browns at the edges.", "Let stand for 5 minutes and serve warm."], tip:"Make the crêpes for nalysnyky thinner than usual, otherwise after baking in sour cream they turn thick and rubbery.", side:"Tea or berry kompot", next:null, alt:{airfryer:"Baking the nalysnyky in a dish: 170 °C, 12-15 minutes."}},
  "x_ua_kruchenyky": {n:"Kruchenyky: Ukrainian pork rolls with mushrooms", how:["Put 1 egg in cold water, bring to a boil and cook for 10 minutes, then cool in cold water.", "While the egg cooks, cut 450 g pork across the grain into 1 cm thick slices.", "Cover the meat with cling film and pound to 4-5 mm, working from the centre outwards, then salt and season with mixed pepper.", "Finely dice 100 g onion and 150 g mushrooms.", "Melt 20 g butter in a frying pan over medium heat and fry the onion and mushrooms for 8 minutes until the liquid evaporates and they turn golden, then salt.", "Peel and finely chop the egg and chop the dill.", "Mix the mushrooms with the egg and half the dill and let the filling cool for 5 minutes.", "Put a spoonful of filling on each slice, roll up tightly, tucking in the sides, and secure with a toothpick.", "Heat 30 ml oil in a frying pan over high heat and brown the rolls for 5-6 minutes, turning, until browned on all sides.", "Preheat the oven to 180 °C and transfer the rolls to a baking dish.", "Thin 120 g sour cream with 100 ml hot water and pour over the rolls.", "Cover the dish with foil and bake for 35 minutes, then uncover and bake 10 minutes more until the meat is tender.", "Remove the toothpicks, spoon over the sauce from the dish and sprinkle with the remaining dill."], tip:"Pound the meat through cling film from the centre outwards so the slice is even and has no holes, otherwise the filling leaks out during baking.", side:"Mashed potatoes", next:{n:"Kruchenyky medallions in sour cream sauce", how:["Cut the cold rolls into 2 cm thick rounds.", "Put them in a frying pan with the leftover sauce and add 2 tbsp water.", "Heat, covered, over low heat for 5-6 minutes and sprinkle with dill."]}, alt:{multi:"After browning, pour over the sour cream sauce and cook on \"Stew\" for 40 minutes instead of in the oven."}},
  "x_ph_ginataang_kalabasa": {n:"Ginataang kalabasa: Filipino squash and green beans in coconut milk", how:["Rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes.", "While the rice cooks, peel 400 g pumpkin and cut into 2 cm cubes, and cut 200 g green beans into 5 cm lengths.", "Slice 80 g onion into half-rings, finely chop 20 g garlic and 20 g ginger and cut 30 g sweet pepper into strips.", "Heat 20 ml oil in a saucepan over medium heat and fry the garlic, onion and ginger for 3 minutes until soft.", "Add the pumpkin and fry for 2 minutes, stirring, to coat the cubes in oil.", "Pour in 300 ml coconut milk and 100 ml water, add 20 ml soy sauce and bring to a boil.", "Reduce to low heat and cook for 10 minutes without bubbling until the pumpkin is tender when tested with a knife.", "Add the beans and pepper and cook 4-5 minutes more until the beans are bright green.", "Mash a few pumpkin cubes with a spoon to thicken the sauce.", "Taste and salt as needed.", "Divide the rice among plates and serve the stew hot."], tip:"Once the coconut milk comes to a boil, keep it on low heat without bubbling, otherwise it splits and the sauce turns grainy.", side:"", next:{n:"Coconut soup with squash and rice", how:["Transfer the leftover stew to a saucepan and add 200 ml water.", "Bring to a boil over medium heat and mash some of the pumpkin.", "Add the leftover rice, heat for 3 minutes and sprinkle with soy sauce."]}, alt:{multi:"Stew: \"Stew\" mode for 20 minutes, beans and pepper for the last 5 minutes."}},
  "x_ph_lumpiang_sariwa": {n:"Lumpiang sariwa: Filipino fresh spring rolls with vegetables and tofu", how:["Beat 1 egg with 65 g flour, keeping 15 g back for the sauce, add a pinch of salt and 150 ml water and whisk to a smooth thin batter; rest for 10 minutes.", "While the batter rests, cut 200 g sweet potato into 1 cm cubes, 100 g carrot and 100 g green beans into 5 cm matchsticks and 150 g cabbage into fine shreds.", "Cut 150 g tofu into 1 cm cubes, finely chop 80 g onion and 30 g garlic, and divide the garlic into two portions.", "Heat a 20 cm frying pan over medium heat and grease with a drop of oil.", "Cook 6 very thin crêpes for 40 seconds per side without letting them brown, stacking them under a towel.", "Toast 30 g walnuts in a dry frying pan for 3 minutes and chop finely.", "Heat the remaining oil in the frying pan and fry the tofu for 5 minutes until golden, then push it to the side.", "Add the onion and half the garlic for 1 minute, then the sweet potato, cover and cook for 5 minutes until half-soft.", "Add the carrot, beans and cabbage, drizzle with 1 tbsp soy sauce and stir-fry for 4 minutes so the vegetables stay crunchy.", "Tip the filling into a colander and cool for 10 minutes to let the juices drain.", "For the sauce, combine the remaining soy sauce, 30 g sugar, 150 ml water, the reserved flour and the remaining garlic in a saucepan.", "Cook the sauce over medium heat, stirring, for 2-3 minutes until thick like kissel.", "Spoon filling onto each crêpe, fold into a parcel, pour over the sauce and sprinkle with nuts."], tip:"Cool the filling and let the juices drain before wrapping, otherwise the thin crêpe goes soggy and tears.", side:"", next:{n:"Crispy fried lumpia", how:["Fold the remaining crêpes and filling into tight parcels.", "Fry in a frying pan with 1 tbsp oil over medium heat for 2 minutes per side until crisp.", "Serve with the reheated sauce and nuts."]}, alt:{}},
  "x_ph_tinola": {n:"Tinola: Filipino chicken soup with ginger and greens", how:["Chop 500 g chicken thighs through the bone into 5 cm pieces.", "Peel 40 g ginger and cut into fine matchsticks, cut 100 g onion into wedges and finely chop 20 g garlic.", "Peel 300 g zucchini and cut into 1.5 cm thick slices, and rinse the spinach.", "Heat 20 ml oil in a pot over medium heat and fry the garlic, onion and ginger for 3 minutes until fragrant.", "Add the chicken and 1 tbsp fish sauce and fry for 5 minutes until the meat is white on all sides.", "Pour in 1 l water, bring to a boil and skim off the foam.", "Simmer over low heat for 25 minutes until the meat comes away from the bone easily.", "While the chicken cooks, rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes.", "Add the zucchini to the soup and cook for 5 minutes until the slices turn translucent.", "Add the spinach and turn off the heat after 1 minute.", "Season with mixed pepper and fish sauce to taste.", "Ladle the soup into bowls and serve the rice separately."], tip:"Fry the ginger until fragrant right at the start instead of just dropping it in the water: that makes tinola broth warming and aromatic.", side:"", next:null, alt:{multi:"Browning on \"Fry\" for 8 minutes, then \"Soup\" for 30 minutes, zucchini and spinach for the last 6 minutes.", pressure:"Cook the chicken with water for 10 minutes under pressure instead of 25 minutes."}},
  "x_ph_bistek_tagalog": {n:"Bistek Tagalog: Filipino beef and onions in soy sauce", how:["Cut 400 g beef across the grain into 5 mm slices and pound lightly through cling film to 3 mm.", "Squeeze the lemon juice and crush 20 g garlic.", "Mix 60 ml soy sauce, the lemon juice, garlic, 2 tsp sugar and mixed pepper.", "Pour the marinade over the meat, toss and leave for 30 minutes.", "While the meat marinates, rinse 180 g rice, add 360 ml water and cook covered over low heat for 15 minutes.", "Slice 200 g onion into 5 mm rings and separate them.", "Heat 30 ml oil in a frying pan over medium heat and fry the onion rings for 2 minutes until softened but still crunchy, then transfer to a plate.", "Lift the meat out of the marinade, keeping the marinade.", "Sear the slices in a single layer over high heat for 1 minute per side, in two batches if needed.", "Pour in the marinade and 80 ml water, cover and simmer over low heat for 15 minutes until tender.", "Return the onion on top of the meat and heat for 2 minutes.", "Divide the rice among plates and top with the meat and onion, spooning over the sauce."], tip:"Return the onion at the very end and heat for just a couple of minutes: in bistek the rings should keep their shape and a slight crunch.", side:"", next:{n:"Fried rice with beef and onion", how:["Cut the leftover meat into 1 cm strips.", "Heat a frying pan with 1 tsp oil over high heat and fry the rice for 3 minutes.", "Add the meat with onion and 2 tbsp sauce and fry 2 minutes more, stirring."]}, alt:{multi:"After searing, the meat with marinade and water: \"Stew\" for 25 minutes instead of the pan.", pressure:"After searing, 8 minutes under pressure instead of 15 minutes of simmering."}},
  "x_fi_porkkanalaatikko": {n:"Porkkanalaatikko: Finnish carrot and rice casserole", how:["Rinse 80 g rice until the water runs clear.", "Cover the rice with 500 ml milk in a saucepan and bring to a boil over medium heat.", "Reduce to low heat and cook for 20 minutes, stirring often, to a thick porridge.", "While the porridge cooks, peel 400 g carrots and grate on the finest grater.", "Mix the carrots into the porridge and cool for 10 minutes so the egg won't curdle later.", "Preheat the oven to 180 °C and grease a baking dish with 10 g butter.", "Beat the egg with a fork with 30 g sugar and a pinch of salt.", "Pour the egg into the carrot and rice mixture and mix well.", "Spread the mixture in the dish about 3 cm deep and smooth with a spoon.", "Cut the remaining 20 g butter into small cubes and scatter over the surface.", "Bake for 50 minutes until the top is browned and the edges pull away from the sides.", "Let the casserole stand for 10 minutes and cut into squares."], tip:"Swap part of the sugar for dark brown cane sugar to get the caramel flavour of the Finnish Christmas casserole.", side:"Sour cream or plain yogurt", next:null, alt:{multi:"Spread the mixture in the greased bowl, \"Bake\" mode for 50-60 minutes."}},
  "x_fi_kesakeitto": {n:"Kesäkeitto: Finnish summer vegetable soup with milk", how:["Peel 300 g potatoes and cut into 1.5 cm cubes, and slice 150 g carrot into 5 mm rounds.", "Break 250 g cauliflower into small florets.", "Cut 100 g green beans into 2 cm pieces and drain the peas.", "Bring 600 ml water to a boil in a pot, salt, add the carrot and cook for 5 minutes.", "Add the potatoes and cauliflower and cook over medium heat for 10 minutes until the potatoes are tender.", "Add the green beans and cook 5 minutes more until bright green.", "Stir 20 g flour into 100 ml cold milk until lump-free.", "Pour in the flour mixture and the remaining 400 ml milk, stirring.", "Heat the soup over low heat for 5 minutes without letting it boil hard, so the milk doesn't curdle.", "Add the peas, heat for 1 minute and finely chop the dill.", "Take off the heat, add 20 g butter and the dill and cover for 5 minutes."], tip:"Add the milk only once the vegetables are soft, and after that keep the soup just below a boil, otherwise it will split.", side:"Rye bread", next:null, alt:{multi:"Vegetables with water on \"Soup\" for 20 minutes, beans 5 minutes before the end, then the milk and flour on \"Keep warm\" for 10 minutes."}},
  "x_fi_pinaattiletut": {n:"Pinaattiletut: Finnish spinach pancakes", how:["Rinse 2 bunches of spinach, remove the thick stems and pat the leaves dry with a towel.", "Melt 20 g butter and let cool until warm.", "Put the spinach in a blender with 200 ml milk and blend for 1 minute to a smooth green purée.", "Beat 2 eggs with 2 tsp sugar and a pinch of salt.", "Pour in the spinach purée, the remaining 200 ml milk and the melted butter and mix.", "Gradually add 150 g flour, whisking to the consistency of thick cream.", "Let the batter rest for 15 minutes so the flour swells.", "Heat a frying pan over medium heat and grease with a thin layer of the remaining butter.", "Pour in 2 tbsp batter at a time, spreading into 10 cm pancakes.", "Cook for 2 minutes per side until the surface looks dry, greasing the pan with butter after each batch.", "Stack the finished pancakes under a towel to keep warm.", "Serve warm."], tip:"The batter needs 15 minutes' rest, otherwise the flour won't swell and the pancakes will tear when you flip them.", side:"Sour cream or lingonberry jam", next:{n:"Warm spinach pancakes for breakfast", how:["Heat a dry frying pan over medium heat.", "Warm the pancakes for 30 seconds per side.", "Roll each one up and serve in a stack."]}, alt:{}},
  "x_fi_kaalilaatikko": {n:"Kaalilaatikko: Finnish cabbage and mince casserole", how:["Rinse 80 g rice, add 200 ml salted water and cook over low heat for 12 minutes until half-cooked and the water is absorbed.", "While the rice cooks, cut 500 g cabbage into 1.5 cm squares and finely dice 100 g onion.", "Melt 15 g butter in a wide frying pan and cook the cabbage over medium heat for 15 minutes until soft and lightly golden.", "Sprinkle the cabbage with 20 g sugar and cook 3 minutes more so it caramelises slightly.", "In another frying pan fry 250 g mince with the onion over medium heat for 8 minutes, breaking up clumps, until no longer pink.", "Preheat the oven to 175 °C and grease a baking dish with the remaining butter.", "Combine the cabbage, mince and rice, salt and season with mixed pepper.", "Pour in 200 ml milk and mix.", "Spread the mixture in the dish and level it.", "Bake for 30 minutes, then stir once and level again.", "Bake 30 minutes more until the top has a deep golden crust.", "Let stand for 10 minutes and serve."], tip:"Without caramelising the cabbage with sugar the casserole tastes flat: that step gives it the slightly sweet Finnish flavour.", side:"Lingonberry jam", next:{n:"Pan-crisped cabbage casserole", how:["Heat a frying pan with 1 tsp butter over medium heat.", "Press the leftover casserole into the pan in a tight layer.", "Fry for 5 minutes without stirring until crusty underneath, then turn over in large pieces for 2 minutes."]}, alt:{multi:"Spread the mixture in the greased bowl, \"Bake\" mode for 50 minutes, stirring halfway."}},
  "x_fr_piperade": {n:"Basque piperade with eggs", how:["Seed 400 g sweet peppers and cut into 1 cm wide strips.", "Slice 150 g onion into thin half-rings and finely chop 10 g garlic.", "Bring water to a boil, score a cross in 400 g tomatoes and drop them into the boiling water for 1 minute.", "Peel the tomatoes and cut the flesh into 1 cm cubes.", "Heat 30 ml olive oil in a deep frying pan over medium heat and cook the onion for 5 minutes until soft.", "Add the peppers and garlic and cook gently for 10 minutes, stirring, until the peppers are soft.", "Add the tomatoes and sprinkle with 1 tsp paprika and salt.", "Cook uncovered for 10 minutes until the liquid evaporates and the sauce thickens.", "Make 4 wells in the vegetables with a spoon, crack an egg into each and salt lightly.", "Cover and cook over low heat for 4-5 minutes until the whites set and the yolks stay runny.", "While the eggs cook, toast slices of bread in a second dry frying pan for 1 minute per side.", "Serve the piperade straight from the pan with the bread."], tip:"The real Basque heat comes from Espelette pepper; you can use a pinch of hot paprika sprinkled over the finished dish instead.", side:"", next:{n:"Piperade toasts", how:["Keep some of the vegetable sauce aside without eggs.", "Reheat it in a frying pan for 3 minutes until bubbling.", "Toast slices of bread and spoon the hot piperade on top."]}, alt:{oven:"After adding the eggs, put the ovenproof pan in the oven at 190 °C for 6-8 minutes instead of covering it."}},
  "x_fr_soupe_pistou": {n:"Soupe au pistou: Provençal vegetable soup with basil", how:["Finely dice 100 g onion, and peel and cut 100 g carrot and 200 g potatoes into 1 cm cubes.", "Cut 200 g zucchini into 1.5 cm cubes, 100 g green beans into 2 cm pieces and 200 g tomatoes into cubes.", "Drain and rinse the canned beans.", "Heat 1 tbsp olive oil in a pot over medium heat and fry the onion for 4 minutes until translucent.", "Add the carrot, potatoes and tomatoes, pour in 1 l water and salt.", "Bring to a boil and cook over medium heat for 15 minutes.", "Add the zucchini, green beans, canned beans and 50 g small pasta.", "Cook 10 minutes more until the pasta is done.", "While the soup cooks, pick the basil leaves and peel 20 g garlic.", "Blend the basil, garlic, remaining olive oil and a pinch of salt for 30 seconds to a green paste.", "Take the soup off the heat and let it stand for 3 minutes to stop boiling.", "Ladle into bowls and add a big spoonful of pistou to each, stirring it in right in the bowl."], tip:"Add the pistou only once the soup is off the heat: boiling turns the basil dark and kills its aroma.", side:"Toasted bread", next:null, alt:{multi:"Onion on \"Fry\" for 4 minutes, then \"Soup\" for 25 minutes, zucchini, beans and pasta for the last 10 minutes."}},
  "x_fr_hachis_parmentier": {n:"Hachis parmentier: French mince and mashed potato bake", how:["Peel 600 g potatoes, cut into large pieces, cover with water, salt and cook for 20 minutes after boiling until completely soft.", "While the potatoes cook, cut 100 g onion and 100 g carrot into fine 5 mm dice and finely chop 10 g garlic.", "Melt 15 g butter in a frying pan over medium heat and fry the onion and carrot for 6 minutes until soft.", "Add 350 g mince and the garlic and fry for 8 minutes, breaking up clumps, until no longer pink.", "Stir in 30 g tomato paste, add 50 ml water, salt, season with mixed pepper and simmer for 5 minutes until thick.", "Preheat the oven to 200 °C.", "Heat 120 ml milk until hot.", "Drain the potatoes and mash with the hot milk and the remaining 25 g butter to a smooth purée.", "Grate 60 g cheese on a medium grater.", "Spread the mince in a baking dish in an even layer, top with the mash and run a fork over it to make ridges.", "Sprinkle with the cheese and bake for 20 minutes until browned.", "Let stand for 5 minutes and cut into portions."], tip:"Always heat the milk for the mash: cold milk makes the potatoes gluey and greyish.", side:"Fresh cucumber salad", next:{n:"Hachis parmentier with a crisp crust", how:["Cut the cold bake into portions.", "Place in a frying pan cheese side up, add 2 tbsp water and cover.", "Heat over low heat for 7-8 minutes until the cheese melts again."]}, alt:{airfryer:"Dish up to 20 cm: 180 °C, 12-15 minutes until browned."}},
  "x_fr_brandade": {n:"Brandade: French salt cod and potato purée", how:["Salt 350 g cod fillet and leave for 10 minutes, then rinse off the salt.", "Peel 300 g potatoes, cut into pieces, cover with water and cook for 20 minutes until soft.", "While the potatoes cook, put the cod in a saucepan, pour over 300 ml milk and add 1 bay leaf and 20 g crushed garlic.", "Heat gently over low heat for 8 minutes without boiling until the fish turns white and opaque.", "Lift out the cod and flake it, removing any bones; discard the bay leaf and keep the milk with the garlic.", "Preheat the oven to 200 °C.", "Drain the potatoes and mash them while hot.", "Add the fish and the garlic from the milk.", "Gradually pour in 50 ml olive oil and 100 ml of the warm fish milk, blending on low speed for 30 seconds to a fluffy but still flaky texture.", "Grease an ovenproof dish with the remaining oil, spread in the brandade and level it.", "Bake for 10 minutes until golden in spots, putting the bread slices on the rack alongside to toast for 5 minutes.", "Finely chop the parsley, sprinkle over the brandade and serve with the toasted bread."], tip:"Blend brandade for no more than 30 seconds, otherwise the potatoes turn gluey and the fish loses its texture.", side:"Fresh tomato salad", next:{n:"Hot brandade toasts", how:["Cut bread into 1.5 cm thick slices.", "Spread thickly with the leftover brandade.", "Bake in the oven at 200 °C for 6-8 minutes until golden in spots and sprinkle with parsley."]}, alt:{airfryer:"Baking the brandade in a dish: 190 °C, 7-8 minutes."}},
  "x_hr_blitva": {n:"Blitva: Dalmatian potatoes with greens and garlic", how:["Put a pot with 1.5 l water on the heat and salt it.", "Peel 500 g potatoes and cut into 2 cm cubes.", "Rinse 2 bunches of spinach, cut off the thick stems and chop them into 1 cm pieces, and tear the leaves roughly by hand.", "Add the potatoes to the boiling water and cook over medium heat for 10 minutes.", "Add the stems and cook 3 minutes more.", "Add the spinach leaves and cook for 2 minutes until soft.", "While the vegetables cook, slice 20 g garlic thinly.", "Reserve 3 tbsp of the cooking water and drain the vegetables in a colander.", "Warm the garlic in 50 ml olive oil in a small pan over low heat for 2 minutes until fragrant without letting it colour.", "Pour the garlic oil and reserved water over the potatoes and spinach and salt.", "Roughly mash with a potato masher, leaving some chunks.", "Sprinkle with the juice of half a lemon and serve warm."], tip:"In Dalmatia blitva is made with Swiss chard, so if you find it at the market use it instead of spinach, and don't skimp on the olive oil.", side:"Baked fish", next:{n:"Crispy blitva patties", how:["Shape the cold blitva into patties 1.5 cm thick.", "Fry in 1 tbsp olive oil over medium heat for 4 minutes per side until crisp.", "Sprinkle with lemon juice and serve."]}, alt:{steamer:"Steam the potatoes for 15 minutes, adding the spinach for the last 3 minutes, instead of boiling; replace the cooking water with 3 tbsp hot water."}},
  "x_hr_sataras": {n:"Sataraš: Croatian stewed peppers with tomatoes and egg", how:["Slice 150 g onion into half-rings.", "Seed 400 g peppers and cut into 1 cm wide strips.", "Bring water to a boil, scald 350 g tomatoes for 1 minute, peel and cut into cubes.", "Heat 30 ml oil in a deep frying pan over medium heat and fry the onion for 5 minutes until golden.", "Add the peppers, cover and cook for 10 minutes, stirring, until soft.", "Add the tomatoes, sprinkle with 1 tsp paprika and salt.", "Cook uncovered for 8 minutes until the sauce thickens.", "Beat 2 eggs with a fork with a pinch of salt.", "Pour the eggs into the vegetables and cook for 2-3 minutes, stirring gently, until they set in soft curds.", "Cut the bread into large pieces.", "Serve the sataraš hot with bread."], tip:"Add the tomatoes only once the peppers are soft, otherwise the peppers stay tough in the acidic sauce.", side:"", next:{n:"Sataraš toasts", how:["Toast slices of bread in a dry frying pan for 1 minute per side.", "Reheat the leftover sataraš in a frying pan for 3 minutes.", "Spoon the hot vegetables onto the toasts and sprinkle with a pinch of paprika."]}, alt:{multi:"Onion on \"Fry\" for 5 minutes, peppers and tomatoes on \"Stew\" for 20 minutes, eggs on \"Fry\" for 3 minutes."}},
  "x_hr_pasticada": {n:"Pašticada: Dalmatian braised marinated beef", how:["Cut 35 g bacon into thin strips and split 15 g garlic cloves in half.", "Make 8 deep cuts with a knife in a 430 g piece of beef and stuff them with the bacon and garlic.", "Rub the meat with salt and mixed pepper, cover with a mixture of 35 ml vinegar and 300 ml water and marinate for at least 30 minutes, ideally overnight in the fridge.", "Slice 140 g onion into half-rings and 110 g carrot into 5 mm rounds.", "Lift out the meat and pat dry with a towel, keeping the marinade.", "Heat 20 ml olive oil in a heavy pot over high heat and brown the beef for 3 minutes on each side until dark.", "Add the onion and carrot and cook over medium heat for 10 minutes until soft.", "Stir in 22 g tomato paste, 1.5 tsp sugar, 30 g raisins and 2 bay leaves.", "Pour in the marinade and enough water to come halfway up the meat and bring to a boil.", "Cover and simmer over low heat for 2.5 hours, turning the meat every 30 minutes and adding water if the sauce reduces too much.", "10 minutes before the end, cook 140 g pasta in salted water according to the packet and drain.", "Lift out the meat, remove the bay leaves and blend the vegetables and sauce with a stick blender until smooth.", "Taste the sauce and adjust the acidity and sweetness if needed.", "Slice the beef 1 cm thick and warm in the sauce for 5 minutes.", "Divide the pasta among plates, top with the meat and pour over the sauce."], tip:"The sauce should be thick, dark and sweet-sour, so adjust the vinegar and sweetness to taste at the very end.", side:"", next:{n:"Pasta with pašticada meat sauce", how:["Finely chop the leftover meat.", "Warm it in the leftover sauce in a frying pan for 5 minutes, adding 2 tbsp water.", "Cook a fresh portion of pasta or reheat the leftovers and toss with the sauce."]}, alt:{multi:"After browning, \"Stew\" mode for 3 hours instead of the stove.", pressure:"After browning, 60 minutes under pressure with natural release instead of 2.5 hours."}},
  "x_hr_gregada": {n:"Gregada: Hvar-style fish and potato stew", how:["Peel 400 g potatoes and slice into 7 mm rounds.", "Slice 150 g onion into thin half-rings and 20 g garlic into slices.", "Cut 400 g cod into 5 cm pieces, salt, season with mixed pepper and sprinkle with the juice of half a lemon.", "Finely chop the parsley and bring water to a boil.", "Pour 30 ml olive oil into a wide heavy-based pot and layer the potatoes, onion and garlic, salting each layer.", "Pour in hot water to barely cover the potatoes, add 10 ml vinegar and bring to a boil.", "Cover and cook over medium heat for 15 minutes until the potatoes are almost tender.", "Lay the fish pieces on top, drizzle with the remaining oil and sprinkle with half the parsley.", "Cook for 10 minutes without stirring, just shaking the pot by the handles so the starch thickens the sauce.", "Check the fish: the flesh should be white and flake easily.", "Sprinkle with the remaining parsley and the juice of the other half lemon.", "Serve in deep plates with bread for the sauce."], tip:"Don't stir gregada with a spoon, shake the pot instead: the fish stays whole and the oil and cooking liquid emulsify into a thick sauce.", side:"", next:{n:"Fish soup from leftover gregada", how:["Break the fish into pieces and lightly mash the potatoes.", "Pour in 400 ml water and bring to a boil.", "Simmer for 3 minutes, sprinkle with parsley and serve with bread."]}, alt:{multi:"Potato layers with water on \"Stew\" for 20 minutes, then the fish for 12 minutes more without stirring."}},
  "x_cz_bramboraky": {n:"Bramboráky: Czech potato pancakes with marjoram", how:["Peel 600 g potatoes and grate finely.", "Put the grated potato in a sieve and squeeze out the excess liquid by hand.", "Press 20 g garlic through a garlic press.", "Mix the potatoes with the egg, garlic, salt and mixed pepper.", "Pour in 50 ml milk and add 60 g flour, mixing to a thick batter that holds on a spoon.", "Line a plate with paper towels.", "Heat a 3 mm layer of oil in a frying pan over medium heat until it shimmers.", "Drop in the batter by the tablespoon and spread into thin pancakes 5 mm thick.", "Fry for 3-4 minutes per side until crisp and deep golden.", "Add more oil between batches and stir the batter if liquid has collected.", "Drain the finished pancakes on paper towels.", "Serve hot."], tip:"Bramboráky should be thin: thick ones don't cook through and stay raw inside.", side:"Sour cream and cucumber salad", next:{n:"Bramboráky baked with egg", how:["Lay the cooled pancakes in a frying pan in a single layer.", "Beat 1 egg with 2 tbsp milk and a pinch of salt and pour over the pancakes.", "Cover and cook over low heat for 5 minutes until the egg sets."]}, alt:{airfryer:"Brush the pancakes on baking paper with oil, 200 °C, 12-14 minutes, turning halfway.", waffle:"2 tbsp batter at a time in a greased waffle iron, 5-6 minutes until crisp."}},
  "x_cz_cocka_na_kyselo": {n:"Čočka na kyselo: Czech sour lentils", how:["Rinse 200 g lentils and soak in cold water for 20 minutes.", "Drain, cover the lentils with 700 ml fresh water, add 1 bay leaf and bring to a boil.", "Simmer over low heat without salt for 25 minutes until tender, skimming off the foam.", "While the lentils cook, finely dice 150 g onion into 5 mm pieces.", "Heat 40 ml oil in a frying pan over medium heat and fry the onion for 6 minutes until golden brown.", "Add 30 g flour and cook, stirring, for 2 minutes until it smells nutty.", "Pour 150 ml of the lentil cooking liquid into the roux and stir to a thick lump-free sauce.", "Add the roux to the lentils and salt.", "Add 30 ml vinegar, 2 tsp sugar and 1 tsp mustard and cook for 5 minutes until thick like porridge.", "Remove the bay leaf and taste: adjust the sourness and sweetness with vinegar or sugar.", "Serve hot with a slice of bread."], tip:"Add the vinegar only at the end: in acidic water lentils stop softening and stay hard.", side:"Pickled cucumbers", next:{n:"Sour lentil soup with croutons", how:["Thin the leftover lentils with 300 ml water and bring to a boil.", "Simmer for 3 minutes and taste for salt and sourness.", "Toast bread cubes in a dry frying pan for 4 minutes and add to the soup."]}, alt:{multi:"Lentils with water on \"Porridge\" or \"Boil\" for 25 minutes, then the roux and seasonings for 5 minutes more."}},
  "x_cz_bramboracka": {n:"Bramboračka: Czech potato soup with mushrooms", how:["Peel 400 g potatoes and cut into 1.5 cm cubes, cut 100 g carrot into 1 cm cubes and finely chop 100 g onion.", "Slice 150 g mushrooms 5 mm thick and finely chop 20 g garlic.", "Heat 20 ml oil in a pot over medium heat and fry the onion and carrot for 5 minutes.", "Add the mushrooms and fry for 7 minutes until the liquid evaporates and they brown.", "Add the potatoes, 1 bay leaf and 1/2 tsp caraway, pour in 1 l water and salt.", "Bring to a boil and cook over medium heat for 20 minutes until the potatoes are tender.", "5 minutes before the potatoes are done, heat the remaining oil in a frying pan and toast 20 g flour for 2 minutes until light brown.", "Loosen the flour with a ladle of soup, stirring until lump-free.", "Pour the roux into the soup, add the garlic and simmer 5 minutes more until lightly thickened.", "Finely chop the parsley and remove the bay leaf.", "Sprinkle the soup with parsley and let stand, covered, for 5 minutes."], tip:"A handful of dried porcini, soaked in advance and added with their soaking water, makes bramboračka truly Czech.", side:"Rye bread", next:null, alt:{multi:"Onion, carrot and mushrooms on \"Fry\" for 12 minutes, then \"Soup\" for 25 minutes, the flour roux with garlic for the last 5 minutes."}},
  "x_cz_segedinsky_gulas": {n:"Segedínský guláš: Czech pork and sauerkraut-style goulash", how:["Cut 450 g pork into 3 cm cubes and finely dice 200 g onion.", "Finely shred 400 g cabbage, rub with 1 tsp salt and 20 ml vinegar and leave for 5 minutes.", "Heat 30 ml oil in a heavy pot over medium heat and fry the onion for 8 minutes until golden.", "Take the pot off the heat, add 1 tbsp paprika and 1/2 tsp caraway and stir quickly so the paprika doesn't burn.", "Add the pork, salt and pour in 200 ml water.", "Return the pot to low heat, cover and simmer for 30 minutes.", "Add the cabbage with its juices and 1 bay leaf and top up with 150 ml water.", "Simmer 35 minutes more until the meat is tender, stirring every 10 minutes.", "Stir 20 g flour into 150 ml cream until lump-free.", "Pour into the goulash and heat, stirring, for 5 minutes until thickened, without letting it boil hard.", "Remove the bay leaf and taste for salt.", "Ladle the goulash into deep plates."], tip:"Add the paprika to the onion off the heat: burnt paprika turns bitter and ruins the whole goulash.", side:"Boiled potatoes", next:{n:"Goulash soup with cabbage", how:["Transfer the leftover goulash to a pot and add 400 ml water.", "Bring to a boil over medium heat and simmer for 5 minutes.", "Taste for salt and serve with bread."]}, alt:{multi:"Onion on \"Fry\" for 8 minutes, meat on \"Stew\" for 30 minutes, cabbage for 40 minutes more, cream and flour for the last 5 minutes.", pressure:"Meat with cabbage and water for 20 minutes under pressure, then the cream and flour without pressure for 5 minutes."}},
  "x_ch_birchermuesli": {n:"Bircher muesli with grated apple", how:["Mix 100 g rolled oats with 200 ml milk and 20 g raisins.", "Cover the bowl and leave for 30 minutes, or better overnight in the fridge.", "Roughly chop 30 g walnuts.", "Toast the nuts in a dry frying pan over medium heat for 3 minutes until fragrant, stirring, and tip onto a plate.", "Wash 2 apples and remove the cores.", "Coarsely grate the apples with the skin on.", "Immediately sprinkle the grated apple with the juice of half a lemon so it doesn't brown.", "Add the apples and 150 g yogurt to the soaked oats and mix.", "Sweeten with 30 g honey and taste, adding more lemon juice if you like.", "Divide among bowls, sprinkle with the nuts and serve at once."], tip:"Dr Bircher-Benner conceived it as an apple dish, so there should be more grated apple than oats by volume.", side:"", next:null, alt:{micro:"Toast the nuts in the microwave for 1.5-2 minutes at 800 W, stirring every 30 seconds."}},
  "x_ch_cholera": {n:"Cholera: Swiss potato, apple and cheese pie", how:["Mix 250 g flour with a pinch of salt, add 110 g cold butter in cubes and rub in with your hands to crumbs.", "Pour in 80 ml ice water, quickly bring the dough together, wrap in cling film and chill for 30 minutes.", "While the dough chills, boil 300 g potatoes in their skins for 20 minutes until half-cooked.", "Slice 150 g onion into half-rings and fry in the remaining 20 g butter over medium heat for 8 minutes until soft and golden.", "Cool the potatoes, peel and slice into 5 mm rounds.", "Core 2 apples and cut into thin wedges, and slice 150 g cheese thinly.", "Preheat the oven to 200 °C.", "Roll out two thirds of the dough 4 mm thick and line a 22 cm tin with sides.", "Layer the potatoes, onion, apples and cheese, seasoning with salt and mixed pepper, finishing with cheese.", "Roll out the remaining dough, cover the pie, crimp the edges and cut a steam hole in the centre.", "Beat the egg and brush over the top of the pie.", "Bake for 45 minutes until deep golden.", "Let the pie cool for 10 minutes and slice."], tip:"If you have leeks, use them for half the onion, as they do in Valais, and the filling will be more delicate.", side:"Green salad", next:{n:"Warm cholera for lunch", how:["Cut the cold pie into pieces.", "Warm in a dry frying pan, covered, over low heat for 6-7 minutes.", "Serve with fresh apple slices."]}, alt:{multi:"Assembled pie in the greased bowl, \"Bake\" mode for 60 minutes; the top will stay pale."}},
  "x_ch_mehlsuppe": {n:"Basler Mehlsuppe: Basel toasted flour soup", how:["Halve 50 g carrot and half the onion, about 75 g, cover with 1 l water and add 1 bay leaf.", "Simmer the stock over medium heat for 15 minutes, strain and keep warm.", "While the stock simmers, finely dice the remaining onion.", "Toast 60 g flour in a dry heavy-based pot over medium heat for 10-12 minutes, stirring constantly, until the colour of milky cocoa and nutty smelling.", "Add 40 g butter and the onion and fry 3 minutes more.", "Take the pot off the heat and let cool for 2 minutes.", "Pour in the warm stock in a thin stream, whisking vigorously so no lumps form.", "Bring to a boil, salt, season with mixed pepper and simmer over low heat for 20 minutes until velvety.", "While the soup simmers, finely grate 60 g cheese.", "Slice the bread and toast in a dry frying pan for 2 minutes per side.", "Ladle the soup into plates, sprinkle with cheese and serve with the croutons."], tip:"The colour of the toasted flour is everything: too pale tastes of paste, too dark turns bitter; aim for the colour of hazelnuts.", side:"", next:null, alt:{multi:"Stock on \"Soup\" for 15 minutes, toast the flour on the stove, then combine and simmer on \"Stew\" for 20 minutes."}},
  "x_ch_capuns": {n:"Capuns: Swiss spinach-leaf rolls with sausage", how:["Mix 150 g flour with 2 eggs, 100 ml milk and a pinch of salt.", "Beat with a spoon for 5 minutes to a thick bubbly batter and let stand for 15 minutes.", "While the batter rests, cut 100 g sausages into 3 mm dice and finely chop the parsley.", "Stir the sausages and parsley into the batter.", "Bring a pot of water to a boil and have a bowl of ice water ready.", "Pick the 16 largest leaves from 2 bunches of spinach, blanch in boiling water for 20 seconds, transfer to the ice water and pat dry; chop the rest of the spinach.", "Put 1 tbsp batter on each leaf and roll up tightly, tucking in the sides.", "Finely chop 80 g onion and fry in 30 g butter in a wide frying pan over medium heat for 4 minutes, then add the chopped spinach for 1 minute.", "Lay the rolls on the onion seam side down, pour in 150 ml cream and 200 ml water so the liquid comes halfway up.", "Cover and simmer gently over low heat for 20 minutes until the batter inside is firm.", "While the capuns simmer, preheat the oven to 200 °C and grate 60 g cheese.", "Transfer the capuns and sauce to a baking dish, sprinkle with cheese and bake for 8 minutes until the cheese melts."], tip:"Capuns should simmer quietly: at a hard boil the leaves unroll and the batter leaks out.", side:"Boiled potatoes", next:{n:"Capuns in cream sauce, reheated in a pan", how:["Transfer the leftover capuns and sauce to a frying pan and add 3 tbsp water.", "Cover and heat over low heat for 6-7 minutes.", "Sprinkle with chopped parsley and serve."]}, alt:{airfryer:"Baking with cheese in a dish: 190 °C, 5-6 minutes."}},
  "x_lk_ala_thel_dala": {n:"Ala thel dala: Sri Lankan spicy fried potatoes", how:["Wash 500 g potatoes, cover with water in a pot, salt and add a pinch of turmeric.", "Boil in their skins for 15 minutes after the water boils, until cooked but not falling apart.", "Drain and let the potatoes cool for 10 minutes.", "While the potatoes cool, slice 150 g onion into thin half-rings and finely chop 20 g garlic.", "Peel the potatoes and cut into 2 cm cubes.", "Heat 50 ml oil in a frying pan over medium heat and fry the onion for 6 minutes until golden.", "Add the garlic, 1 tsp curry powder, 1/2 tsp turmeric and mixed pepper and fry for 30 seconds until fragrant.", "Add the potatoes and salt.", "Fry for 6-7 minutes, turning gently, until the cubes are coated in spices and crisp at the edges.", "Take off the heat and sprinkle with lime juice.", "Serve hot."], tip:"Boil the potatoes the day before if you can: cold potatoes don't crumble when fried and soak up the spices better.", side:"Boiled rice", next:{n:"Warm potato salad with lime", how:["Warm the leftover potatoes in a dry frying pan for 3-4 minutes.", "Transfer to a bowl and sprinkle with lime juice.", "Sprinkle with mixed pepper and serve warm."]}, alt:{airfryer:"Toss the boiled potato cubes with the spices and 2 tbsp oil: 200 °C, 12-15 minutes, shaking; fry the onion separately.", micro:"Potatoes in their skins: in a covered bowl for 8-10 minutes at 800 W instead of boiling."}},
  "x_lk_wambatu_moju": {n:"Wambatu moju: Sri Lankan caramelised eggplant pickle", how:["Cut 500 g eggplant into 5 x 1 cm batons, toss with salt and 1/2 tsp turmeric and leave for 15 minutes.", "While the eggplant stands, slice 150 g onion into thin half-rings and finely chop 20 g garlic and 20 g ginger.", "Squeeze out the released liquid and pat the eggplant dry with a towel.", "Rinse 150 g rice, add 300 ml water and cook covered over low heat for 15 minutes.", "Heat 150 ml oil in a frying pan over medium heat to 180 °C.", "Fry the eggplant in batches for 4 minutes until deep golden and drain on paper towels.", "Heat 1 tbsp of the eggplant frying oil in a saucepan and fry the onion, garlic and ginger for 4 minutes.", "Add 40 ml vinegar, 20 g sugar, 1 tsp mustard, the remaining turmeric and 1 tsp curry powder.", "Reduce for 2 minutes to a syrup.", "Stir in the eggplant and heat for 3 minutes until coated in the glossy sauce.", "Let the moju stand for 10 minutes.", "Serve with rice."], tip:"Moju tastes better the next day, so make it ahead and keep it in a jar in the fridge for up to 5 days.", side:"", next:{n:"Fried rice with moju", how:["Heat a frying pan with 1 tsp oil over high heat.", "Fry the leftover rice for 3 minutes, breaking up any clumps.", "Stir in 3-4 tbsp moju and fry 2 minutes more."]}, alt:{airfryer:"Drizzle the eggplant with 2 tbsp oil: 200 °C, 14-16 minutes, shaking every 5 minutes, instead of frying in oil.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_lk_wattakka_curry": {n:"Wattakka curry: Sri Lankan pumpkin in coconut milk", how:["Peel and seed 500 g pumpkin and cut into 2.5 cm cubes.", "Slice 100 g onion into thin half-rings and finely chop 20 g garlic and 20 g ginger.", "Rinse 150 g rice until the water runs clear, add 300 ml water and cook covered over low heat for 15 minutes.", "Heat 20 ml oil in a saucepan over medium heat and fry the onion for 4 minutes until soft.", "Add the garlic and ginger and fry for 1 minute.", "Add 1 tsp curry powder and 1/2 tsp turmeric and toast for 30 seconds, stirring.", "Add the pumpkin, salt and stir so the cubes are coated in spices.", "Pour in 150 ml water and cook covered over low heat for 10 minutes until the pumpkin is almost tender.", "Pour in 200 ml coconut milk and simmer uncovered over low heat for 5 minutes without letting it boil hard.", "When the sauce has thickened and the pumpkin starts to break down at the edges, taste for salt.", "Divide the rice among plates and serve the curry on top."], tip:"Once the coconut milk is in, don't boil it hard, otherwise it splits and the sauce turns grainy.", side:"", next:{n:"Thick pumpkin and coconut soup", how:["Mash the leftover curry with a fork in a saucepan.", "Pour in 200 ml water and bring to a boil over medium heat.", "Heat for 3 minutes, salt and serve with the leftover rice."]}, alt:{multi:"Pumpkin with spices and water on \"Stew\" for 15 minutes, coconut milk for the last 5 minutes."}},
  "x_lk_isso_curry": {n:"Isso curry: Sri Lankan shrimp in coconut sauce", how:["If the shrimp are frozen, thaw them in cold water for 15 minutes.", "Peel 350 g shrimp, remove the veins, toss with 1/2 tsp turmeric and salt and leave for 10 minutes.", "Rinse 150 g rice, add 300 ml water and cook covered over low heat for 15 minutes.", "Slice 100 g onion into thin half-rings, cut 150 g tomatoes into 1 cm cubes and finely chop 20 g garlic and 20 g ginger.", "Heat 20 ml oil in a saucepan over medium heat and fry the onion for 5 minutes until golden.", "Add the garlic and ginger and fry for 1 minute.", "Add 1 tsp curry powder and 1/2 tsp paprika and toast for 30 seconds.", "Add the tomatoes and cook for 4 minutes until soft.", "Pour in 200 ml coconut milk and bring to a gentle simmer.", "Add the shrimp and cook for 3-4 minutes until pink and curled.", "Take off the heat and sprinkle with lime juice.", "Divide the rice among plates and serve the curry on top."], tip:"Add the shrimp at the very end and keep them in the sauce for no more than 4 minutes, otherwise they turn rubbery.", side:"", next:{n:"Rice with shrimp in coconut sauce", how:["Heat a frying pan over medium heat and add the leftover rice.", "Add the leftover curry and 2 tbsp water.", "Heat, covered, for 3-4 minutes without overcooking the shrimp and sprinkle with lime."]}, alt:{multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_ee_seenekaste": {n:"Seenekaste: Estonian mushroom sour cream sauce with potatoes", how:["Peel 500 g potatoes, halve them, cover with water and salt.", "Cook over medium heat for 20 minutes after boiling until tender.", "While the potatoes cook, clean 350 g mushrooms and slice 5 mm thick, and finely dice 120 g onion.", "Melt 30 g butter in a frying pan and fry the onion over medium heat for 4 minutes until translucent.", "Add the mushrooms and fry for 10 minutes until their juices evaporate and they brown.", "Sprinkle the mushrooms with 20 g flour, stir and cook for 1 minute.", "Pour in 150 ml hot water, stirring, and simmer for 3 minutes until thickened.", "Add 150 g sour cream, salt and season with mixed pepper.", "Heat over low heat for 2 minutes without boiling.", "Finely chop the dill and drain the potatoes.", "Divide the potatoes among plates, pour over the mushroom sauce and sprinkle with dill."], tip:"Wild mushrooms give the best flavour, in Estonia people use chanterelles or porcini, but the sauce is good with button mushrooms too.", side:"Pickled cucumbers", next:{n:"Fried potatoes with mushroom sauce", how:["Slice the cold potatoes into 1 cm rounds.", "Fry in butter over medium heat for 6-7 minutes until crisp.", "Warm the leftover sauce with 2 tbsp water, pour over the potatoes and sprinkle with dill."]}, alt:{steamer:"Steam the potatoes for 25 minutes instead of boiling.", multi:"Potatoes on the rack, \"Steam\" mode for 25 minutes."}},
  "x_ee_kohupiimavormiroog": {n:"Kohupiimavorm: Estonian tvorog bake with raisins", how:["Rinse 40 g raisins and soak in hot water for 10 minutes.", "Preheat the oven to 180 °C.", "Grease a baking dish with 10 g butter and dust with 1 tbsp semolina.", "Mash 400 g tvorog with a fork or press through a sieve until smooth.", "Beat 2 eggs with 50 g sugar and a pinch of salt until pale and frothy.", "Finely grate the zest from the lemon.", "Mix the tvorog with the eggs, the remaining semolina, 50 g sour cream and the zest and leave for 10 minutes so the semolina swells.", "Drain the raisins, pat dry and stir into the mixture.", "Spread the mixture in the dish and level it.", "Brush the top with the remaining 50 g sour cream for a glossy crust.", "Bake for 35 minutes until golden on top and springy in the middle.", "Cool in the dish for 10 minutes and slice."], tip:"The sour cream on top gives a smooth golden crust without cracks, so don't skip this step.", side:"Tea", next:null, alt:{multi:"Mixture in the greased bowl, \"Bake\" mode for 50 minutes.", airfryer:"Dish up to 18 cm: 160 °C, 25-30 minutes."}},
  "x_ee_leivasupp": {n:"Leivasupp: Estonian rye bread soup with apples and cream", how:["Preheat the oven to 180 °C.", "Cut about 300 g rye bread into 2 cm cubes and spread on a baking tray.", "Dry the bread for 10 minutes into rusks.", "Bring 1 l water to a boil, pour over the rusks and leave for 20 minutes until completely soaked.", "While the rusks soak, core the apple and cut into 1 cm cubes, and rinse 50 g raisins.", "Blend the bread and water until smooth.", "Pour the mixture into a pot and add the apple, raisins, 40 g sugar and a pinch of salt.", "Cook over low heat for 10 minutes, stirring often from the bottom, until the apples are soft.", "Add the juice of half a lemon and taste for the balance of sweet and sour.", "Whisk 100 ml cold cream until lightly foamy.", "Serve the soup warm or cold with a spoonful of cream on top."], tip:"The soup thickens as it cools, so the next day thin it with hot water or berry juice.", side:"", next:null, alt:{airfryer:"Rusks: 180 °C, 6-7 minutes, shaking halfway, instead of the oven."}},
  "x_ee_mulgikapsad": {n:"Mulgikapsad: Estonian sauerkraut-style cabbage with pork and barley", how:["Rinse 60 g pearl barley and soak in cold water for 30 minutes.", "While the barley soaks, cut 400 g pork into 4 cm pieces and finely dice 100 g onion.", "Finely shred 500 g cabbage and rub it by hand with 1 tsp salt and 20 ml vinegar.", "Heat 20 ml oil in a heavy pot over medium heat and brown the pork for 8 minutes.", "Add the onion and fry 4 minutes more.", "Drain the barley and spread the cabbage with its juices and the barley over the meat.", "Add 1 bay leaf, salt, season with mixed pepper and pour in 400 ml water.", "Cover and simmer over low heat for 70 minutes, stirring every 20 minutes and adding water if the bottom is dry.", "When 15 minutes of braising remain, peel 400 g potatoes, cover with water, salt and cook for 20 minutes until tender.", "Add 2 tsp sugar to the cabbage, stir and cook uncovered 10 minutes more until the barley is soft and the liquid has almost evaporated.", "Drain the potatoes and remove the bay leaf from the cabbage.", "Serve the cabbage with meat and the potatoes on plates."], tip:"The barley soaks up the sour cabbage juices and pork fat, so add water a little at a time: the dish should be thick, not a soup.", side:"", next:{n:"Fried cabbage with pork and potatoes", how:["Cut the cold potatoes into 2 cm cubes.", "Fry in a frying pan with 1 tbsp oil for 6 minutes until crisp.", "Add the leftover cabbage and meat and fry 5 minutes more, stirring."]}, alt:{multi:"After browning, \"Stew\" mode for 1.5 hours, sugar 10 minutes before the end.", pressure:"Cabbage with meat and barley for 30 minutes under pressure, then the sugar and 10 minutes uncovered."}},
  "x_et_shiro": {n:"Shiro wat: Ethiopian spiced chickpea stew", how:["Toast 120 g dried chickpeas in a dry frying pan over medium heat for 8 minutes until lightly browned, stirring.", "Cool the chickpeas for 10 minutes, grind to a fine flour in a powerful blender and sift.", "Chop 200 g onion very finely, almost to a paste, and finely grate 20 g garlic and 20 g ginger.", "Coarsely grate 150 g tomatoes, discarding the skin, and bring 500 ml water to a boil.", "Dry-cook the onion in a pot without oil over medium heat for 5 minutes, stirring.", "Pour in 50 ml oil and fry the onion 5 minutes more until golden.", "Add the garlic, ginger, 1 tbsp paprika, 1 tsp cumin and mixed pepper and fry for 1 minute.", "Add the tomatoes and cook for 4 minutes.", "Pour in 500 ml hot water and bring to a boil.", "Add the chickpea flour in a thin stream, whisking constantly so no lumps form.", "Simmer over low heat for 10 minutes, stirring, to the consistency of a thick purée; salt and add hot water if needed.", "Warm the lavash in a dry frying pan for 20 seconds per side.", "Serve the shiro hot with lavash, tearing off pieces to scoop up the stew."], tip:"Add the chickpea flour a little at a time and whisk straight away, and keep adjusting the thickness with water until the very end.", side:"Fresh tomatoes", next:{n:"Lavash rolls with shiro", how:["Reheat the leftover shiro in a saucepan for 3 minutes, adding 2 tbsp water.", "Spread the lavash with a thin layer of the stew.", "Roll up tightly and warm in a dry frying pan for 1 minute per side."]}, alt:{}},
  "x_et_atakilt_wat": {n:"Atakilt wat: Ethiopian cabbage, potato and carrot stew", how:["Cut 400 g cabbage into large 3 cm squares.", "Peel 300 g potatoes and cut into 2 cm cubes, and cut 150 g carrot into 5 cm batons.", "Slice 150 g onion into thin half-rings and finely chop 20 g garlic and 20 g ginger.", "Heat 50 ml oil in a wide pot over medium heat and fry the onion for 6 minutes until soft.", "Add the garlic, ginger, 1 tsp turmeric and 1/2 tsp cumin and fry for 1 minute until fragrant.", "Add the carrot and potatoes, salt and stir so the vegetables turn yellow.", "Pour in 150 ml water, cover and cook over medium heat for 10 minutes.", "Spread the cabbage on top and salt lightly without stirring.", "Cover and cook 12 minutes more until the cabbage is soft and the potatoes are easily pierced with a knife.", "Stir gently without mashing the potatoes.", "Heat uncovered for 3 minutes to cook off excess water, then serve."], tip:"Lay the cabbage over the potatoes and don't stir: that way it steams gently and doesn't turn to mush.", side:"Flatbread", next:{n:"Crispy-bottomed atakilt", how:["Heat a frying pan with 1 tbsp oil over medium heat.", "Press the leftover vegetables into the pan in a tight layer.", "Fry for 5 minutes without stirring until crisp underneath, then turn over and heat for 2 minutes."]}, alt:{multi:"Onion with spices on \"Fry\" for 7 minutes, then the vegetables with water, cabbage on top, \"Stew\" for 25 minutes."}},
  "x_et_fosolia": {n:"Fosolia: Ethiopian green beans with carrots", how:["Rinse 150 g rice, add 300 ml salted water, bring to a boil and cook covered over low heat for 15 minutes.", "While the rice cooks, cut 350 g green beans into 5 cm lengths and 200 g carrot into thin batons of the same length.", "Slice 150 g onion into thin half-rings and finely chop 20 g garlic and 20 g ginger.", "Finely dice 100 g tomatoes.", "Heat 40 ml oil in a deep frying pan over medium heat and fry the onion for 5 minutes until golden.", "Add the garlic and ginger and fry for 1 minute.", "Add the tomatoes and cook for 2 minutes until soft.", "Add the carrots and beans, salt, season with mixed pepper and pour in 50 ml water.", "Cover and cook for 8 minutes.", "Uncover and fry 3 minutes more, stirring, until the vegetables are tender but still slightly crisp.", "Divide the rice among plates and serve the fosolia alongside."], tip:"Cut the beans and carrots into matching batons so they finish cooking at the same time.", side:"", next:{n:"Fried rice with fosolia", how:["Heat a frying pan with 1 tsp oil over high heat.", "Fry the leftover rice for 3 minutes, breaking up any clumps.", "Add the leftover beans and carrots, season with mixed pepper and fry 3 minutes more."]}, alt:{wok:"In a wok over high heat, cut the covered cooking time to 6 minutes.", multi:"Rice: \"Rice\" or \"Grains\" mode for 25 minutes instead of a pot."}},
  "x_et_kitfo_leb_leb": {n:"Kitfo leb leb: Ethiopian minced beef in spiced butter", how:["Trim 250 g beef of any sinew and pat dry with a towel.", "Chop the meat very finely with a sharp knife to a coarse mince and refrigerate.", "Finely grate 7 g garlic and 7 g ginger.", "Rinse about three quarters of a bunch of spinach and chop roughly.", "Lightly salt 100 g tvorog and put it on a plate.", "Melt 35 g butter in a saucepan over low heat, add the garlic, ginger and 1/2 tsp cumin and warm for 3 minutes without letting the garlic colour.", "Stir in 1/2 tsp paprika and mixed pepper and take off the heat.", "Wilt the spinach in a dry frying pan over medium heat for 2 minutes, salt and transfer to a plate.", "Pour the spiced butter into the frying pan over medium heat and add the beef.", "Stirring constantly, warm the meat for 2-3 minutes until just pink or 5 minutes until fully cooked.", "Salt the meat and take it off the heat at once.", "Warm the lavash in a dry frying pan for 20 seconds per side.", "Serve the meat alongside the spinach and tvorog, with the lavash."], tip:"Use only fresh tenderloin for kitfo and chop it by hand: machine-minced meat releases its juices and turns grey.", side:"", next:{n:"Lavash wrap with kitfo, spinach and tvorog", how:["Reheat the leftover meat in a frying pan for 2 minutes until fully cooked.", "Spread the meat, spinach and tvorog on the lavash.", "Roll up tightly and toast in a dry frying pan for 1 minute per side."]}, alt:{}},
  "x_za_umngqusho": {n:"Umngqusho: South African corn and beans", how:["Drain the corn and beans and rinse the beans with cold water.", "Cut 120 g onion and 200 g tomatoes into 1 cm dice and finely chop 20 g garlic.", "Peel 200 g potatoes and cut into 1.5 cm cubes.", "Heat 30 ml oil in a pot over medium heat and fry the onion for 5 minutes until soft.", "Add the garlic and 1 tsp curry powder and fry for 1 minute.", "Add the tomatoes and cook for 5 minutes until they release their juice.", "Add the potatoes, pour in 300 ml water and salt.", "Cover and cook over medium heat for 12 minutes until the potatoes are tender.", "Add the corn and beans and simmer uncovered over low heat for 10 minutes.", "Mash about a quarter of the mixture right in the pot with a potato masher to make it thick and creamy.", "Finely chop the parsley, sprinkle over the umngqusho and serve hot."], tip:"Real umngqusho is made from dried crushed samp corn, soaked overnight and cooked for 2 hours; canned corn just saves time.", side:"", next:{n:"Thick umngqusho soup", how:["Transfer the leftovers to a pot and add 400 ml water.", "Bring to a boil and simmer for 5 minutes, lightly mashing the potatoes.", "Salt and sprinkle with parsley."]}, alt:{multi:"Onion with curry and tomatoes on \"Fry\" for 8 minutes, then the potatoes with water on \"Stew\" for 25 minutes, adding the corn and beans after 15 minutes."}},
  "x_za_pampoenkoekies": {n:"Pampoenkoekies: South African cinnamon pumpkin fritters", how:["Peel 400 g pumpkin and cut into 3 cm cubes.", "Cover the pumpkin with water, salt and cook for 12 minutes after boiling until soft.", "Drain and dry the pumpkin in the pot over low heat for 2 minutes, shaking.", "Mash the pumpkin to a smooth purée and cool for 10 minutes.", "Stir the egg, 30 ml milk, 20 g sugar and a pinch of salt into the purée.", "Gradually add 100 g flour and mix to a thick batter that slowly drops from a spoon.", "Put the remaining 20 g sugar on a plate for coating.", "Heat 60 ml vegetable oil with 20 g butter in a frying pan over medium heat.", "Drop in the batter by the tablespoon, 3 cm apart.", "Fry the fritters for 2-3 minutes per side until browned.", "Drain on paper towels for 30 seconds.", "Immediately roll in the sugar and serve warm."], tip:"Always dry the pumpkin after boiling: a watery purée needs more flour and the fritters turn rubbery.", side:"Tea", next:null, alt:{micro:"Pumpkin in a covered bowl with 2 tbsp water: 800 W, 7-8 minutes instead of boiling.", steamer:"Steam the pumpkin for 15 minutes instead of boiling; no need to dry it."}},
  "x_za_melktert": {n:"Melktert: South African milk tart with cinnamon", how:["Mix 150 g flour with a pinch of salt, add 60 g cold butter and 30 g sugar and rub to crumbs.", "Separate the yolk of one egg, add it to the crumbs with 2 tbsp cold water and bring the dough together, keeping the white.", "Roll the dough out 3 mm thick, line a 22 cm tin, prick with a fork and chill for 15 minutes.", "Preheat the oven to 190 °C.", "Cover the pastry with baking paper, set a smaller tin on top as a weight and bake for 15 minutes until pale golden.", "While the case bakes, heat 500 ml milk with the remaining 20 g butter until almost boiling.", "Whisk the second egg and the reserved white with 70 g sugar, 30 g flour and 20 g semolina until smooth.", "Pour the hot milk into the egg mixture in a thin stream, stirring.", "Return to the saucepan and cook over low heat for 5-6 minutes, stirring constantly, until thick like custard.", "Remove the weight from the case and lower the oven to 180 °C.", "Pour the custard into the case and level it.", "Bake for 15 minutes until the centre no longer wobbles when you shake the tin.", "Cool the tart for at least 30 minutes until fully set and slice."], tip:"Dust the cinnamon over the tart the moment it comes out of the oven: it sticks to the hot surface and gives the signature spiced top.", side:"Tea or coffee", next:null, alt:{}},
  "x_za_tamatiebredie": {n:"Tamatiebredie: South African lamb and tomato stew", how:["Cut 500 g lamb into 4 cm pieces, salt and season with mixed pepper.", "Slice 200 g onion into half-rings, finely chop 20 g garlic and cut 400 g tomatoes into 1.5 cm cubes.", "Heat 30 ml oil in a heavy pot over high heat and brown the lamb in batches for 4 minutes each.", "Return all the meat, add the onion and cook over medium heat for 7 minutes until soft.", "Add the garlic and fry for 1 minute.", "Add the fresh tomatoes, a can of whole tomatoes in juice, 2 tsp sugar and 1 bay leaf, and pour in 150 ml water.", "Bring to a boil, cover and simmer over low heat for 60 minutes, stirring every 20 minutes.", "Towards the end of the braising, peel 300 g potatoes and cut into 3 cm chunks.", "Add the potatoes to the stew and simmer 25 minutes more until the potatoes and meat are tender.", "While the potatoes cook, rinse 150 g rice, add 300 ml salted water and cook covered over low heat for 15 minutes.", "Remove the bay leaf and taste the sauce for salt.", "Divide the rice among plates and serve the bredie on top."], tip:"Bredie is even better the next day, once the tomatoes have fully cooked down and the sauce is thick and slightly sweet.", side:"", next:{n:"Tomato soup with lamb and rice", how:["Transfer the leftover bredie to a pot and add 400 ml water.", "Cut large pieces of meat and potato smaller and bring to a boil.", "Add the leftover rice, simmer for 5 minutes and salt to taste."]}, alt:{multi:"After browning, \"Stew\" mode for 1.5 hours, potatoes 30 minutes before the end.", pressure:"Meat with tomatoes for 25 minutes under pressure, then the potatoes for 5 minutes more under pressure."}},
  "x_jp_nikujaga": {n:"Nikujaga: Japanese beef and potato stew", how:["Put 200 g beef in the freezer for 20 minutes to make thin slicing easier.", "While the meat chills, peel 400 g potatoes and cut into 4 cm chunks, cut 100 g carrot into 2 cm diagonal pieces and 150 g onion into 1 cm wedges.", "Slice the beef very thinly, 2-3 mm.", "Rinse 150 g rice, add 180 ml water and cook covered over low heat for 12 minutes, then take off the heat and leave covered.", "Heat 10 ml oil in a pot over high heat and fry the beef for 1 minute until it changes colour.", "Add the onion, potatoes and carrot and fry for 2 minutes, stirring.", "Pour in 300 ml water, bring to a boil and skim off the foam.", "Add 30 g sugar and simmer for 5 minutes.", "Pour in 40 ml soy sauce.", "Cover with a round of baking paper placed directly on the food and simmer over medium heat for 15 minutes until the potatoes are soft and the liquid has reduced by half.", "Divide the nikujaga among bowls with a little sauce and serve with rice."], tip:"Add the sugar before the soy sauce, otherwise the salt stops the sweetness from soaking into the potatoes.", side:"", next:{n:"Nikujaga donburi", how:["Reheat the leftover nikujaga in a saucepan for 4-5 minutes.", "Break the potatoes up slightly with a spoon.", "Spoon over hot rice and pour over the sauce."]}, alt:{multi:"Browning on \"Fry\" for 3 minutes, then water, sugar and soy sauce, \"Stew\" for 25 minutes.", pressure:"After adding the soy sauce, 5 minutes under pressure with quick release."}},
  "x_jp_kabocha_nimono": {n:"Kabocha nimono: Japanese pumpkin simmered in soy sauce", how:["Rinse 150 g rice, add 200 ml water and cook covered over low heat for 12 minutes, then leave covered for 10 minutes.", "While the rice cooks, seed 400 g pumpkin and peel off strips of skin here and there.", "Cut the pumpkin into 4 cm pieces and lightly trim the sharp edges of each piece.", "Peel 10 g ginger and cut into fine matchsticks.", "Arrange the pumpkin in a saucepan in a single layer, skin side down.", "Pour in 250 ml water, add 20 g sugar and the ginger and bring to a boil.", "Cover with a round of baking paper and simmer over medium heat for 8 minutes.", "Pour in 30 ml soy sauce and simmer 6 minutes more, only shaking the pan, until the pumpkin is soft and the liquid has almost boiled away.", "Take off the heat and let the pumpkin cool in the sauce for 5 minutes.", "Toast 10 g sesame seeds in a dry small pan for 1-2 minutes until golden.", "Divide the rice and pumpkin among bowls, pour over the remaining sauce and sprinkle with sesame."], tip:"Don't stir the pumpkin with a spoon while it simmers, just shake the pan, otherwise the pieces fall apart.", side:"", next:{n:"Cold bento with pumpkin nimono", how:["Pack the cooled rice into a container.", "Arrange the pumpkin pieces snugly alongside and spoon over some sauce.", "Sprinkle with sesame and take it with you: nimono is eaten cold."]}, alt:{multi:"Pumpkin with water, sugar and ginger on \"Stew\" for 15 minutes, soy sauce after 8 minutes."}},
  "x_jp_okonomiyaki": {n:"Okonomiyaki: Japanese cabbage pancake", how:["Shred 300 g cabbage into thin 3 cm strips and coarsely grate 50 g carrot.", "Mix 100 g flour with 120 ml cold water and a pinch of salt to a smooth lump-free batter.", "For the sauce, mix 3 tbsp ketchup, 10 ml soy sauce and 2 tsp sugar.", "Snip the nori finely with scissors.", "Beat 2 eggs into the batter and mix.", "Add the cabbage and carrot and fold gently without beating.", "Heat 10 ml oil in a 20 cm frying pan over medium heat and spread in half the mixture as a round 2 cm thick.", "Cook covered for 5 minutes until golden underneath.", "Flip the pancake using a plate and cook 5 minutes more until firm in the middle.", "Repeat with the remaining oil and mixture.", "Brush the okonomiyaki with the sauce and pipe a criss-cross of mayonnaise over it.", "Sprinkle with nori and serve hot."], tip:"Add the cabbage to the batter just before frying and fold gently: that way the pancake turns out fluffy rather than dense.", side:"", next:{n:"Reheated crispy okonomiyaki", how:["Store the pancakes without sauce and mayonnaise.", "Warm in a dry frying pan, covered, over low heat for 3 minutes per side.", "Brush with sauce, add mayonnaise and sprinkle with nori."]}, alt:{}},
  "x_jp_agedashi_tofu": {n:"Agedashi tofu in ginger sauce", how:["Wrap 400 g tofu in paper towels, weigh down with a plate and leave for 15 minutes.", "While the tofu drains, rinse 150 g rice, add 200 ml water and cook covered over low heat for 12 minutes.", "Tear 1 sheet of nori, cover with 200 ml water and warm in a saucepan for 5 minutes without boiling.", "Strain the broth, add 30 ml soy sauce and 2 tsp sugar and keep hot over the lowest heat.", "Peel 20 g ginger and grate finely.", "Cut the tofu into 4 cm cubes and pat dry again with a towel.", "Heat 100 ml oil in a small frying pan over medium heat to 170 °C.", "Dredge each cube in 40 g flour and shake off the excess.", "Fry the tofu in batches for 2-3 minutes, turning, until crisp and pale golden.", "Drain on paper towels for 30 seconds.", "Divide the tofu among bowls and pour over the hot sauce.", "Top with the grated ginger and serve at once with rice."], tip:"Pour the sauce over only just before serving, otherwise the crisp coating goes soggy.", side:"", next:null, alt:{airfryer:"Drizzle the flour-coated tofu with 1 tbsp oil: 200 °C, 12-14 minutes, shaking halfway."}}
});

